function allowedOrigins() {
  return [
    ...DEFAULT_ALLOWED_ORIGINS,
    ...(Deno.env.get('LL_ALLOWED_ORIGINS') || '').split(','),
  ]
    .map((item) => item.trim())
    .filter(Boolean)
    .filter((item, index, list) => list.indexOf(item) === index);
}

function aiDemoAllowedOrigins() {
  return [
    ...DEFAULT_AI_DEMO_ALLOWED_ORIGINS,
    ...(Deno.env.get('LL_AI_DEMO_ALLOWED_ORIGINS') || '').split(','),
  ]
    .map((item) => item.trim())
    .filter(Boolean)
    .filter((item, index, list) => list.indexOf(item) === index);
}

function isAllowedOrigin(origin: string) {
  return !origin || allowedOrigins().includes(origin);
}

function isAiDemoAllowed(origin: string) {
  if (!origin) return false;
  const enabledFlag = Deno.env.get('LL_AI_DEMO_ENABLED');
  if (!aiDemoAllowedOrigins().includes(origin)) return false;
  return enabledFlag === 'true';
}

function readEdgeSecret(name: string) {
  const direct = Deno.env.get(name);
  if (direct) return direct;
  if (name === 'SUPABASE_SERVICE_ROLE_KEY') {
    const serviceRoleFallback = Deno.env.get('LL_SERVICE_ROLE_KEY')
      || Deno.env.get('SERVICE_ROLE_KEY')
      || Deno.env.get('supabase_service_role_key');
    if (serviceRoleFallback) return serviceRoleFallback;
  }
  const secretKeys = Deno.env.get('SUPABASE_SECRET_KEYS');
  if (name === 'SUPABASE_SERVICE_ROLE_KEY' && secretKeys) {
    try {
      const parsed = JSON.parse(secretKeys) as Record<string, string>;
      const firstKey = Object.keys(parsed)[0];
      return parsed.default || parsed.service_role || (firstKey ? parsed[firstKey] : '');
    } catch {
      return '';
    }
  }
  const publishableKeys = Deno.env.get('SUPABASE_PUBLISHABLE_KEYS');
  if (name === 'SUPABASE_ANON_KEY' && publishableKeys) {
    try {
      const parsed = JSON.parse(publishableKeys) as Record<string, string>;
      const firstKey = Object.keys(parsed)[0];
      return parsed.default || parsed.anon || (firstKey ? parsed[firstKey] : '');
    } catch {
      return '';
    }
  }
  return '';
}

function jsonResponse(body: unknown, status = 200, origin = '') {
  const headers = new Headers({
    'content-type': 'application/json; charset=utf-8',
    'access-control-allow-methods': 'POST, OPTIONS',
    'access-control-allow-headers': 'apikey, authorization, content-type, x-client-info',
    vary: 'origin',
  });
  if (origin && isAllowedOrigin(origin)) headers.set('access-control-allow-origin', origin);
  return new Response(JSON.stringify(body), { status, headers });
}

function fail(status: number, message: string, origin: string, detail?: unknown) {
  return jsonResponse({ ok: false, status, message, detail }, status, origin);
}

function assertLlAllowlist() {
  return [...WRITE_TABLE_ALLOWLIST, ...EDIT_TARGET_TABLE_ALLOWLIST].every((table) => table.startsWith('public.ll_'));
}

function safeAction(value: unknown) {
  return String(value || '').replace(/^\/+/u, '').trim();
}

function firstDefined(...values: unknown[]) {
  return values.find((value) => value !== undefined && value !== null && value !== '');
}

function firstPresent(...values: unknown[]) {
  return values.find((value) => value !== undefined && value !== null);
}

function hasMeaningfulInvestmentLoanData(row: Record<string, unknown>) {
  const kind = safeText(firstDefined(row.tranche_type, row.capital_kind));
  if (kind && kind !== 'loan') return true;
  const amount = Number(firstDefined(row.committed_amount_krw, row.drawn_amount_krw, row.amount_krw) || 0);
  return amount > 0
    || !!safeText(firstDefined(row.party_name, row.counterparty_name, row.lender_name))
    || !!safeText(row.drawdown_date)
    || !!safeText(row.maturity_date)
    || !!safeText(firstDefined(row.interest_rate, row.loan_rate, row.all_in_rate, row.spread_rate))
    || !!safeText(firstDefined(row.loan_type, row.loan_period));
}

function normalizePublicLlTable(value: unknown) {
  const raw = String(value || '').trim();
  const table = raw.startsWith('public.') ? raw : `public.${raw}`;
  if (!/^public\.ll_[a-zA-Z0-9_]+$/u.test(table)) return '';
  return table;
}

function clientTableName(publicTable: string) {
  return publicTable.replace(/^public\./u, '');
}

function isSafeIdentifier(value: unknown) {
  return /^[a-zA-Z_][a-zA-Z0-9_]*$/u.test(String(value || ''));
}

function normalizeText(value: unknown) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

function normalizeComparableEditValue(value: unknown) {
  return normalizeText(value)
    .trim()
    .replace(/^\s*(?:없음|해당\s*없음|N\/?A|NA|null|[-–—])\s*(?:[|｜]\s*)?/iu, '')
    .trim();
}

function valuesEqual(a: unknown, b: unknown) {
  const left = normalizeComparableEditValue(a);
  const right = normalizeComparableEditValue(b);
  if (left === right) return true;
  if (!left || !right) return false;
  const leftNumber = Number(left.replace(/,/gu, ''));
  const rightNumber = Number(right.replace(/,/gu, ''));
  return Number.isFinite(leftNumber) && Number.isFinite(rightNumber) && Math.abs(leftNumber - rightNumber) < 0.000001;
}

const DATA_MANAGEMENT_BOOLEAN_FIELDS = new Set([
  'is_preleased',
  'is_3pl',
  'is_single_tenant',
  'sublease_yn',
  'is_subleased',
  'office_use_yn',
  'prelease_yn',
  'third_party_logistics_yn',
  'single_tenant_yn',
]);

function dataManagementBooleanComparable(value: unknown) {
  const normalized = normalizeComparableEditValue(value).toLowerCase();
  if (['true', '1', 'y', 'yes', '예'].includes(normalized)) return 'true';
  if (['false', '0', 'n', 'no', '아니오', ''].includes(normalized)) return 'false';
  return normalized;
}

function dataManagementReviewStatusComparable(value: unknown) {
  const normalized = normalizeComparableEditValue(value).toLowerCase();
  if (/매각|sold|disposed|archived/iu.test(normalized)) return 'sold';
  if (/리뷰|검토|review_required|suspected_error/iu.test(normalized)) return 'review';
  if ([
    '',
    'normal',
    '정상',
    'active',
    'source_repaired',
    'dashboard_latest_history_applied',
    '검토 완료',
  ].includes(normalized)) return 'normal';
  return `raw:${normalized}`;
}

function dataManagementFieldValuesEqual(fieldName: unknown, a: unknown, b: unknown) {
  const field = safeText(fieldName).toLowerCase();
  if (field === 'review_status' || field === 'disposition_status') {
    return dataManagementReviewStatusComparable(a) === dataManagementReviewStatusComparable(b);
  }
  if (DATA_MANAGEMENT_BOOLEAN_FIELDS.has(field)) {
    return dataManagementBooleanComparable(a) === dataManagementBooleanComparable(b);
  }
  if (field === 'temperature_type') {
    return dataManagementLeasePurposeLabel(a) === dataManagementLeasePurposeLabel(b);
  }
  if (field === 'current_manager_name' || field === 'current_manager_email') {
    const left = normalizeComparableEditValue(a);
    const right = normalizeComparableEditValue(b);
    const normalizeUnassigned = (value: string) => (/^(?:미지정|없음)$/u.test(value) ? '' : value);
    return normalizeUnassigned(left) === normalizeUnassigned(right);
  }
  return valuesEqual(a, b);
}

function parseJsonValue(value: unknown, fallback: unknown = null): unknown {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

function stableComparable(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stableComparable);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, child]) => [key, stableComparable(child)]),
  );
}

function jsonValuesEqual(a: unknown, b: unknown) {
  return JSON.stringify(stableComparable(a)) === JSON.stringify(stableComparable(b));
}

function redactSensitivePayload(value: unknown, depth = 0): unknown {
  if (depth > 8) return '[redacted-depth-limit]';
  if (Array.isArray(value)) return value.map((item) => redactSensitivePayload(item, depth + 1));
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([key, child]) => [
    key,
    SENSITIVE_KEY_PATTERN.test(key) ? '[redacted]' : redactSensitivePayload(child, depth + 1),
  ]));
}

function stripUndefined<T extends Record<string, unknown>>(value: T, depth?: number): T & Record<string, unknown>;
function stripUndefined<T>(value: T, depth?: number): T;
function stripUndefined<T>(value: T, depth = 0): T {
  if (depth > 8) return '[depth-limit]' as unknown as T;
  if (Array.isArray(value)) return value.map((item) => stripUndefined(item, depth + 1)) as unknown as T;
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(Object.entries(value as Record<string, unknown>)
    .filter(([, child]) => child !== undefined)
    .map(([key, child]) => [key, stripUndefined(child, depth + 1)])) as T;
}

async function sha256Text(value: string) {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value));
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

async function sha256Bytes(value: Uint8Array | ArrayBuffer) {
  const bytes = value instanceof Uint8Array ? value : new Uint8Array(value);
  const copy = new Uint8Array(bytes.byteLength);
  copy.set(bytes);
  const digest = await crypto.subtle.digest('SHA-256', copy.buffer);
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

function safeStorageFileName(value: unknown) {
  const name = safeText(value || 'market-source')
    .replace(/[\\/:*?"<>|]+/gu, '_')
    .replace(/\s+/gu, ' ')
    .trim()
    .slice(0, 180);
  return name || 'market-source';
}

function safeStorageObjectName(value: unknown, fallbackExtension = '') {
  const extension = safeText(fallbackExtension).replace(/^\./u, '').toLowerCase();
  const baseName = safeText(value || 'market-source')
    .replace(/\.[a-z0-9]+$/iu, '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/gu, '')
    .replace(/[^a-z0-9]+/giu, '-')
    .replace(/^-+|-+$/gu, '')
    .toLowerCase()
    .slice(0, 80) || 'market-source';
  return extension ? `${baseName}.${extension}` : baseName;
}

function fileExtension(value: unknown) {
  const match = safeText(value).toLowerCase().match(/\.([a-z0-9]+)$/u);
  return match?.[1] || '';
}

function coerceValue(nextValue: unknown, currentValue: unknown) {
  if (currentValue === null || currentValue === undefined) return nextValue;
  if (typeof currentValue === 'number') {
    const numeric = Number(String(nextValue).replace(/,/gu, ''));
    return Number.isFinite(numeric) ? numeric : nextValue;
  }
  if (typeof currentValue === 'boolean') {
    return ['true', '1', 'y', 'yes'].includes(String(nextValue).toLowerCase());
  }
  if (typeof currentValue === 'object') {
    try {
      return typeof nextValue === 'string' ? JSON.parse(nextValue) : nextValue;
    } catch {
      return nextValue;
    }
  }
  return nextValue;
}

function coerceDataManagementEditValue(cell: NormalizedEditCell, nextValue: unknown, currentValue: unknown) {
  const fieldName = safeText(cell.fieldName);
  if (['is_preleased', 'is_3pl', 'is_single_tenant', 'sublease_yn', 'is_subleased', 'office_use_yn', 'prelease_yn', 'third_party_logistics_yn', 'single_tenant_yn'].includes(fieldName)) {
    const normalized = safeText(nextValue).trim();
    return nextValue === true || /^(true|1|y|yes|예)$/iu.test(normalized);
  }
  if (fieldName === 'temperature_type') {
    return dataManagementLeasePurposeLabel(nextValue) || null;
  }
  if (fieldName === 'review_status' && safeText(cell.targetTable) === 'public.ll_assets') {
    const status = safeText(nextValue).trim();
    if (/매각|sold|disposed|archived/iu.test(status)) return '매각';
    if (/리뷰|검토|review/iu.test(status)) return '리뷰 필요';
    return '정상';
  }
  return coerceValue(nextValue, currentValue);
}

function checkRateLimit(userId: string, action: string, limit = 30, windowMs = 60_000) {
  const key = `${userId}:${action}`;
  const now = Date.now();
  const bucket = rateBuckets.get(key);
  if (!bucket || bucket.resetAt <= now) {
    rateBuckets.set(key, { resetAt: now + windowMs, count: 1 });
    return true;
  }
  bucket.count += 1;
  return bucket.count <= limit;
}

function permissionMatchesJwtUser(profile: Record<string, unknown>, jwtUserId: string) {
  return isActivePermission(profile) && safeText(profile.user_id) === jwtUserId;
}

async function getContext(request: Request, origin: string): Promise<Context> {
  const supabaseUrl = Deno.env.get('SUPABASE_URL');
  const anonKey = readEdgeSecret('SUPABASE_ANON_KEY');
  const serviceRoleKey = readEdgeSecret('SUPABASE_SERVICE_ROLE_KEY');
  if (!supabaseUrl || !anonKey || !serviceRoleKey) throw new Response('Server is not configured', { status: 500 });

  const authHeader = request.headers.get('authorization') || '';
  const jwt = authHeader.replace(/^Bearer\s+/i, '').trim();
  if (!jwt) throw new Response('Missing Authorization token', { status: 401 });

  const authClient = createClient(supabaseUrl, anonKey, {
    global: { headers: { Authorization: `Bearer ${jwt}` } },
  });
  const { data: userData, error: userError } = await authClient.auth.getUser(jwt);
  if (userError || !userData.user) throw new Response('Invalid Authorization token', { status: 401 });

  const serviceClient = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data, error } = await serviceClient
    .from('ll_user_permissions')
    .select('*')
    .eq('user_id', userData.user.id)
    .limit(2);
  if (error) throw new Response('Failed to read logistics permission', { status: 500 });
  const profiles = ((data || []) as Record<string, unknown>[])
    .filter((profile) => permissionMatchesJwtUser(profile, userData.user.id));
  if (profiles.length > 1) throw new Response('Ambiguous active logistics profile', { status: 403 });
  const permission = profiles[0] || null;

  if (!permission) throw new Response('Active logistics profile is required', { status: 403 });

  const role = safeText(permission?.logistics_role, 'Reader');
  return { serviceClient, user: { id: userData.user.id, email: userData.user.email || null }, permission, role, origin };
}

async function audit(serviceClient: SupabaseClient, userId: string | null, action: string, status: number, payload: unknown) {
  // API request traces are deliberately not persisted. User-visible writes keep their
  // own readback state in ll_edit_requests and login time in ll_user_permissions.
  void serviceClient;
  void userId;
  void action;
  void status;
  void payload;
}

async function auditOptional(serviceClient: SupabaseClient, userId: string | null, action: string, status: number, payload: unknown) {
  try {
    await audit(serviceClient, userId, action, status, payload);
    return null;
  } catch (error) {
    const message = String((error as Error)?.message || error || 'Failed to write API audit log');
    console.error(`[ll-dashboard-api] ${action} audit failed: ${message}`);
    return message;
  }
}

async function denyDashboardRead(ctx: Context, action: string, status: number, message: string, reason: string) {
  await audit(ctx.serviceClient, ctx.user.id, `${action}/denied`, status, { reason });
  return fail(status, message, ctx.origin);
}

function managedAssetCodes(permission: Record<string, unknown> | null) {
  return Array.isArray(permission?.managed_asset_codes) ? permission.managed_asset_codes.map((item) => String(item)) : [];
}

function permissionAccountStatus(permission: Record<string, unknown> | null) {
  return String(permission?.account_status || '').trim().toLowerCase();
}

function isActivePermission(permission: Record<string, unknown> | null) {
  return Boolean(permission && permissionAccountStatus(permission) === 'active');
}

function userFeaturePermissions(permission: Record<string, unknown> | null) {
  const explicit = permission?.feature_permissions;
  const source = explicit && typeof explicit === 'object' && !Array.isArray(explicit)
    ? { ...(explicit as Record<string, unknown>) }
    : {};
  return {
    ...source,
    ...Object.fromEntries([...LOGISTICS_FEATURE_KEYS].map((key) => [key, source[key] === true])),
  };
}

function hasUserFeaturePermission(permission: Record<string, unknown> | null, featureKey: string) {
  return userFeaturePermissions(permission)?.[featureKey] === true;
}

function assetRefVariants(value: unknown) {
  const raw = String(value || '').trim();
  if (!raw) return [];
  const compact = raw.replace(/\s+/gu, '');
  const variants = new Set([raw, compact, raw.toLowerCase(), compact.toLowerCase(), raw.toUpperCase(), compact.toUpperCase()]);
  const assetIdMatch = compact.match(/^asset[_-](.+)$/iu);
  if (assetIdMatch?.[1]) variants.add(assetIdMatch[1].toUpperCase());
  if (/^[A-Z]{1,2}P?\d{5,}$/iu.test(compact) || /^[AS]\d{5,}$/iu.test(compact)) {
    variants.add(`asset_${compact.toLowerCase()}`);
  }
  return [...variants].filter(Boolean);
}

function hasManagedAssetRef(permission: Record<string, unknown> | null, relatedAssetId: unknown) {
  const managedRefs = new Set(managedAssetCodes(permission).flatMap(assetRefVariants));
  return assetRefVariants(relatedAssetId).some((item) => managedRefs.has(item));
}

function hasManagedAssetReference(permission: Record<string, unknown> | null, relatedAssetId: unknown, relatedAssetName?: unknown) {
  const managedRefs = new Set(managedAssetCodes(permission).flatMap(assetRefVariants));
  return [
    ...assetRefVariants(relatedAssetId),
    ...assetRefVariants(relatedAssetName),
  ].some((item) => managedRefs.has(item));
}

function permissionFlag(permission: Record<string, unknown> | null, key: 'managed_asset_permissions' | 'other_asset_permissions', action: 'read' | 'create' | 'update' | 'delete') {
  const value = permission?.[key] as Record<string, unknown> | undefined;
  return value?.[action] === true;
}

type AssetCrudAction = 'read' | 'create' | 'update' | 'delete';
type CanonicalAsset = Record<string, unknown> & { asset_id: string; asset_code?: string | null; asset_name?: string | null };

function requestedAssetReferences(value: unknown) {
  const values = Array.isArray(value) ? value : [value];
  return [...new Set(values.flatMap((item) => {
    if (Array.isArray(item)) return item;
    if (item && typeof item === 'object' && !Array.isArray(item)) {
      const row = item as Record<string, unknown>;
      return [row.asset_id, row.assetId, row.asset_code, row.assetCode, row.asset_name, row.assetName];
    }
    return [item];
  }).map((item) => safeText(item)).filter(Boolean))];
}

async function resolveCanonicalAssets(ctx: Context, references: unknown) {
  const requested = requestedAssetReferences(references);
  if (!requested.length) return { assets: [] as CanonicalAsset[], error: 'asset reference is required', reasonCode: 'asset_reference_required' };
  const { data, error } = await ctx.serviceClient
    .from('ll_assets')
    .select('asset_id,asset_code,asset_name,fund_code,fund_name,current_manager_name,current_manager_email')
    .limit(500);
  if (error) return { assets: [] as CanonicalAsset[], error: 'failed to resolve canonical asset', reasonCode: 'asset_resolution_unavailable' };
  const assets = ((data || []) as Record<string, unknown>[])
    .filter((row) => safeText(row.asset_id)) as CanonicalAsset[];
  const resolved: CanonicalAsset[] = [];
  for (const reference of requested) {
    const variants = new Set(assetRefVariants(reference).map((item) => item.toLowerCase()));
    const matches = assets.filter((asset) => [asset.asset_id, asset.asset_code, asset.asset_name]
      .flatMap(assetRefVariants)
      .some((item) => variants.has(item.toLowerCase())));
    if (matches.length !== 1) {
      return {
        assets: [] as CanonicalAsset[],
        error: matches.length ? 'asset reference is ambiguous' : 'asset reference was not found',
        reasonCode: matches.length ? 'asset_reference_ambiguous' : 'asset_reference_unknown',
      };
    }
    if (!resolved.some((asset) => asset.asset_id === matches[0].asset_id)) resolved.push(matches[0]);
  }
  return { assets: resolved, error: '', reasonCode: '' };
}

function permissionRevision(permission: Record<string, unknown> | null) {
  return safeText(firstDefined(permission?.permission_revision, permission?.updated_at, permission?.created_at)) || null;
}

function canonicalAssetIsManaged(permission: Record<string, unknown> | null, asset: CanonicalAsset) {
  const managedRefs = new Set(managedAssetCodes(permission).flatMap(assetRefVariants).map((item) => item.toLowerCase()));
  return [asset.asset_id, asset.asset_code, asset.asset_name]
    .flatMap(assetRefVariants)
    .some((item) => managedRefs.has(item.toLowerCase()));
}

function canonicalAssetCapability(permission: Record<string, unknown> | null, asset: CanonicalAsset) {
  const key = canonicalAssetIsManaged(permission, asset) ? 'managed_asset_permissions' : 'other_asset_permissions';
  return {
    read: permissionFlag(permission, key, 'read'),
    create: permissionFlag(permission, key, 'create'),
    update: permissionFlag(permission, key, 'update'),
    delete: permissionFlag(permission, key, 'delete'),
    scope: key === 'managed_asset_permissions' ? 'managed' : 'other',
  };
}

async function assetCapabilitiesForProfile(ctx: Context, permission: Record<string, unknown> | null = ctx.permission) {
  const { data, error } = await ctx.serviceClient
    .from('ll_assets')
    .select('asset_id,asset_code,asset_name')
    .order('asset_name', { ascending: true })
    .limit(500);
  if (error) return { capabilities: {}, error: 'failed to read canonical assets' };
  const capabilities = Object.fromEntries(((data || []) as Record<string, unknown>[])
    .filter((asset) => safeText(asset.asset_id))
    .map((asset) => [safeText(asset.asset_id), canonicalAssetCapability(permission, asset as CanonicalAsset)]));
  return { capabilities, error: '' };
}

async function evaluateCanonicalAssetPermission(ctx: Context, action: AssetCrudAction, references: unknown) {
  if (!hasPermissionRow(ctx)) return { allowed: false, assets: [] as CanonicalAsset[], error: 'no active logistics permission', reasonCode: 'active_profile_required' };
  const resolved = await resolveCanonicalAssets(ctx, references);
  if (resolved.error || !resolved.assets.length) return { allowed: false, assets: [] as CanonicalAsset[], error: resolved.error || 'asset reference is required', reasonCode: resolved.reasonCode || 'asset_reference_required' };
  const allowed = resolved.assets.every((asset) => canonicalAssetCapability(ctx.permission, asset)[action] === true);
  return { allowed, assets: resolved.assets, error: allowed ? '' : `asset ${action} permission denied`, reasonCode: allowed ? '' : `asset_${action}_denied` };
}

function canWriteRelatedAsset(ctx: Context, relatedAssetId: unknown, relatedAssetName?: unknown) {
  const assetId = String(relatedAssetId || '').trim();
  const assetName = String(relatedAssetName || '').trim();
  if (!assetId && !assetName) return false;
  return hasManagedAssetReference(ctx.permission, assetId, assetName)
    ? permissionFlag(ctx.permission, 'managed_asset_permissions', 'update')
    : permissionFlag(ctx.permission, 'other_asset_permissions', 'update');
}

function canMutateRelatedAsset(ctx: Context, action: 'create' | 'update' | 'delete', relatedAssetId: unknown, relatedAssetName?: unknown) {
  const assetId = String(relatedAssetId || '').trim();
  const assetName = String(relatedAssetName || '').trim();
  if (!assetId && !assetName) return false;
  const managed = hasManagedAssetReference(ctx.permission, assetId, assetName);
  return managed
    ? permissionFlag(ctx.permission, 'managed_asset_permissions', action)
    : permissionFlag(ctx.permission, 'other_asset_permissions', action);
}

function canMutateWorklog(ctx: Context, action: 'create' | 'update' | 'delete', relatedAssetId: unknown) {
  const assetId = String(relatedAssetId || '').trim();
  if (!assetId) return false;
  const permissionKey = assetId && hasManagedAssetRef(ctx.permission, assetId)
    ? 'managed_asset_permissions'
    : 'other_asset_permissions';
  return permissionFlag(ctx.permission, permissionKey, action);
}

function serverWorklogPayload(ctx: Context, rawPayload: unknown, currentPayload: Record<string, unknown> = {}, extra: Record<string, unknown> = {}) {
  const incoming = rawPayload && typeof rawPayload === 'object' && !Array.isArray(rawPayload)
    ? rawPayload as Record<string, unknown>
    : {};
  const {
    role: _role,
    user_id: _userId,
    userId: _userIdCamel,
    permission: _permission,
    permissions: _permissions,
    scope: _scope,
    organization: _organization,
    ownerOrganization: _ownerOrganization,
    author: _author,
    authorId: _authorId,
    createdBy: _createdBy,
    ...safeIncoming
  } = incoming;
  return {
    ...currentPayload,
    ...safeIncoming,
    ...extra,
    organization: currentPayload.organization || ctx.permission?.organization || null,
    server_actor_id: ctx.user.id,
  };
}

function canReadRelatedAsset(ctx: Context, relatedAssetId: unknown, relatedAssetCode?: unknown, relatedAssetName?: unknown) {
  const references = [relatedAssetId, relatedAssetCode, relatedAssetName]
    .map((value) => String(value || '').trim())
    .filter(Boolean);
  if (!references.length) return false;
  const key = references.some((reference) => hasManagedAssetRef(ctx.permission, reference))
    ? 'managed_asset_permissions'
    : 'other_asset_permissions';
  return permissionFlag(ctx.permission, key, 'read');
}

function canReadRelatedAssetRecord(ctx: Context, row: Record<string, unknown>) {
  return canReadRelatedAsset(ctx, row.asset_id, row.asset_code, row.asset_name);
}

function canUseDataQuality(ctx: Context) {
  return hasPermissionRow(ctx) && hasUserFeaturePermission(ctx.permission, 'data_quality');
}

function canManageFeatureAccess(ctx: Context) {
  return hasPermissionRow(ctx) && hasUserFeaturePermission(ctx.permission, 'permission_admin');
}

function compactFeatureAccessUser(row: Record<string, unknown>) {
  const staffName = safeText(firstDefined(row.staff_name, row.name));
  const email = normalizeAuthEmail(row.email);
  const imageUrl = logisticsProfileImageUrl(email, firstDefined(row.image_url, row.avatar_url));
  return {
    email,
    staff_name: staffName,
    organization: safeText(row.organization),
    logistics_role: safeText(row.logistics_role),
    image_url: imageUrl,
    avatar_url: imageUrl,
  };
}

function featureUserKeys(row: Record<string, unknown>) {
  const user = compactFeatureAccessUser(row);
  return [
    user.email,
    user.staff_name,
    user.organization && user.staff_name ? `${user.organization}|${user.staff_name}` : '',
  ]
    .map((value) => String(value || '').trim().toLowerCase())
    .filter(Boolean);
}

function normalizeFeatureAccessConfig(value: unknown) {
  const config = value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
  const featuresInput = config.features && typeof config.features === 'object' && !Array.isArray(config.features)
    ? config.features as Record<string, unknown>
    : {};
  const features: Record<string, unknown> = {};
  for (const key of LOGISTICS_FEATURE_KEYS) {
    const row = featuresInput[key] && typeof featuresInput[key] === 'object' && !Array.isArray(featuresInput[key])
      ? featuresInput[key] as Record<string, unknown>
      : {};
    const users = Array.isArray(row.users)
      ? (row.users as Record<string, unknown>[]).map(compactFeatureAccessUser).filter((user) => user.email || user.staff_name).slice(0, 200)
      : [];
    features[key] = {
      key,
      label: safeText(row.label || key),
      users,
    };
  }
  return {
    features,
    updatedAt: safeText(config.updatedAt || new Date().toISOString()),
  };
}

function featureAccessUserMatches(ctx: Context, row: Record<string, unknown>) {
  const email = String(ctx.permission?.email || actorEmail(ctx) || '').trim().toLowerCase();
  const name = safeText(firstDefined(ctx.permission?.staff_name, ctx.permission?.name, ctx.permission?.display_name, actorName(ctx))).toLowerCase();
  const user = compactFeatureAccessUser(row);
  return Boolean((email && user.email && email === user.email) || (name && user.staff_name && name === user.staff_name.toLowerCase()));
}

async function readFeatureAccessConfig(ctx: Context) {
  const { data: permissionRows, error: permissionError } = await ctx.serviceClient
    .from('ll_user_permissions')
    .select('email,staff_name,organization,image_url,logistics_role,feature_permissions,account_status')
    .order('organization', { ascending: true })
    .order('staff_name', { ascending: true });
  if (permissionError) throw new Error(`Failed to read logistics permissions: ${permissionError.message}`);
  const rows = ((permissionRows || []) as Record<string, unknown>[]).filter(isActivePermission);
  if (rows.length) {
    const features: Record<string, unknown> = {};
    LOGISTICS_FEATURE_KEYS.forEach((key) => {
      const users = rows
        .filter((row) => hasUserFeaturePermission(row, key))
        .map((row) => compactFeatureAccessUser({
          email: row.email,
          staff_name: firstDefined(row.staff_name, staffNameForEmail(row.email)),
          organization: row.organization,
          image_url: firstDefined(row.image_url, LOGISTICS_IMAGE_URL_BY_EMAIL[normalizeAuthEmail(row.email)]),
          logistics_role: row.logistics_role,
        }))
        .filter((row) => row.email || row.staff_name);
      features[key] = { key, label: key, users };
    });
    return normalizeFeatureAccessConfig({ features, updatedAt: new Date().toISOString() });
  }
  const { data, error } = await ctx.serviceClient
    .from('ll_cache_entries')
    .select('payload,response_payload,updated_at')
    .eq('cache_type', LOGISTICS_FEATURE_ACCESS_CACHE_TYPE)
    .eq('cache_key', LOGISTICS_FEATURE_ACCESS_CACHE_KEY)
    .maybeSingle();
  if (error) return normalizeFeatureAccessConfig({});
  return normalizeFeatureAccessConfig(data?.payload || data?.response_payload || {});
}

async function canUseServerFeature(ctx: Context, featureKey: string) {
  if (!hasPermissionRow(ctx)) return false;
  if (!LOGISTICS_FEATURE_KEYS.has(featureKey)) return false;
  if (hasUserFeaturePermission(ctx.permission, featureKey)) return true;
  return false;
}

async function authorizeActionManifest(ctx: Context, action: string) {
  const classification = ACTION_MANIFEST.get(action);
  if (!classification) return fail(404, 'Unknown action', ctx.origin, { reason_code: 'unknown_action' });
  if (classification === 'permission_admin' && !await canUseServerFeature(ctx, 'permission_admin')) {
    return fail(403, 'This action is not available for this account', ctx.origin, { reason_code: 'permission_admin_required' });
  }
  if (classification === 'approval_management' && !await canUseServerFeature(ctx, 'approval_management')) {
    return fail(403, 'This action is not available for this account', ctx.origin, { reason_code: 'approval_management_required' });
  }
  return null;
}

async function authorizeActionScope(ctx: Context, action: string, payload: Record<string, unknown>) {
  const scope = ACTION_SCOPE_MANIFEST.get(action);
  if (!scope) return fail(500, 'Action scope is not classified', ctx.origin, { reason_code: 'action_scope_unclassified' });
  if (scope === 'public') return null;
  if (!hasPermissionRow(ctx)) return fail(403, 'Active logistics profile is required', ctx.origin);
  if (scope === 'self') {
    const requestedActorIds = [payload.user_id, payload.userId, payload.actor_id, payload.actorId, payload.created_by, payload.createdBy]
      .map((value) => safeText(value))
      .filter(Boolean);
    if (requestedActorIds.some((userId) => userId !== ctx.user.id)) {
      return fail(403, 'Self-scoped action cannot target another user', ctx.origin, { reason_code: 'self_scope_mismatch' });
    }
  }
  if (scope === 'asset' || scope === 'multi_asset') {
    if (ACTION_SCOPE_HANDLER_CONTRACTS.get(action) !== scope) {
      return fail(500, 'Asset scope handler contract is invalid', ctx.origin, { reason_code: 'asset_scope_handler_unregistered' });
    }
  }
  return null;
}

async function canUseMarketResearch(ctx: Context) {
  return await canUseServerFeature(ctx, 'ai_chat')
    || await canUseServerFeature(ctx, 'market_research');
}

async function callFeatureAccessGet(ctx: Context) {
  const config = await readFeatureAccessConfig(ctx);
  await auditOptional(ctx.serviceClient, ctx.user.id, 'feature-access/get', 200, {});
  return jsonResponse({ ok: true, data: config }, 200, ctx.origin);
}

async function callFeatureAccessUpdate(ctx: Context, payload: Record<string, unknown>) {
  if (!canManageFeatureAccess(ctx)) return fail(403, 'Feature access management is limited to Planning Center users', ctx.origin);
  const config = normalizeFeatureAccessConfig(payload.config || payload);
  const rawChanges = Array.isArray(payload.changes) ? payload.changes as Record<string, unknown>[] : [];
  const changes = rawChanges
    .map((change) => {
      const featureKey = safeText(firstDefined(change.featureKey, change.feature_key));
      const userInput = change.user && typeof change.user === 'object' && !Array.isArray(change.user)
        ? change.user as Record<string, unknown>
        : change;
      return {
        featureKey,
        enabled: change.enabled === true || change.enabled === 'true',
        user: compactFeatureAccessUser(userInput),
      };
    })
    .filter((change) => change.featureKey && (change.user.email || change.user.staff_name));
  if (changes.length) {
    let createdCount = 0;
    let changedCount = 0;
    for (const change of changes) {
      if (!LOGISTICS_FEATURE_KEYS.has(change.featureKey)) {
        return fail(400, 'Unknown feature permission key', ctx.origin, { feature_key: change.featureKey });
      }
      const email = normalizeAuthEmail(change.user.email);
      if (!email) return fail(400, 'Feature permission user email is required', ctx.origin);
      const { data: existingRows, error: readError } = await ctx.serviceClient
        .from('ll_user_permissions')
        .select('user_id,email,staff_name,organization,image_url,logistics_role,feature_permissions,account_status')
        .ilike('email', email)
        .limit(1);
      if (readError) return fail(500, 'Failed to read feature permission user', ctx.origin);
      const existing = Array.isArray(existingRows) && existingRows.length ? existingRows[0] as Record<string, unknown> : null;
      if (!existing) {
        if (!change.enabled) continue;
        const principal = await resolveExactPermissionPrincipal(ctx.serviceClient, email);
        if (principal.error) {
          return fail(409, 'An exact Auth user is required before feature permissions can be created', ctx.origin, { reason_code: principal.reasonCode });
        }
        const nextFeatures = allLogisticsFeaturePermissions(false);
        nextFeatures[change.featureKey] = true;
        const { error: upsertError } = await ctx.serviceClient
          .from('ll_user_permissions')
          .upsert(stripUndefined({
            user_id: principal.userId,
            email,
            staff_name: safeText(firstDefined(change.user.staff_name, staffNameForEmail(email))),
            organization: safeText(firstDefined(change.user.organization, organizationForEmail(email))),
            image_url: firstDefined(change.user.image_url, logisticsProfileImageUrl(email)),
            logistics_role: safeText(change.user.logistics_role) || 'Reader',
            managed_asset_codes: [],
            managed_asset_permissions: { read: true, create: false, update: false, delete: false },
            other_asset_permissions: { read: false, create: false, update: false, delete: false },
            can_ingest_weekly: false,
            account_status: 'active',
            feature_permissions: nextFeatures,
            profile_payload: { source: 'feature_access_delta_update' },
            updated_at: new Date().toISOString(),
          }), { onConflict: 'email' });
        if (upsertError) return fail(500, 'Failed to create feature permission user', ctx.origin);
        createdCount += 1;
        continue;
      }
      const currentFeatures = existing.feature_permissions as Record<string, unknown> || {};
      const nextFeatures = { ...currentFeatures, [change.featureKey]: change.enabled };
      const featureChanged = Boolean(currentFeatures[change.featureKey]) !== change.enabled;
      const accountStatusChanged = change.enabled && safeText(existing.account_status) !== 'active';
      if (!featureChanged && !accountStatusChanged) continue;
      const { data: updatedRows, error: updateError } = await ctx.serviceClient
        .from('ll_user_permissions')
        .update(stripUndefined({
          feature_permissions: nextFeatures,
          account_status: change.enabled ? 'active' : undefined,
          updated_at: new Date().toISOString(),
        }))
        .eq('user_id', existing.user_id)
        .select('user_id,email');
      if (updateError) return fail(500, 'Failed to save feature permissions', ctx.origin);
      if (!Array.isArray(updatedRows) || updatedRows.length < 1) {
        return fail(409, 'Feature permission user was not found during save readback', ctx.origin, { email });
      }
      changedCount += updatedRows.length;
    }
    const saved = await readFeatureAccessConfig(ctx);
    await auditOptional(ctx.serviceClient, ctx.user.id, 'feature-access/update', 200, { delta: true, changes: changes.length });
    return jsonResponse({ ok: true, data: saved, meta: { delta: true, created_count: createdCount, changed_count: changedCount } }, 200, ctx.origin);
  }
  const { data: permissionRows, error: permissionError } = await ctx.serviceClient
    .from('ll_user_permissions')
    .select('user_id,email,staff_name,organization,image_url,logistics_role,feature_permissions,account_status');
  if (permissionError) return fail(500, 'Failed to read logistics permissions', ctx.origin);

  const desiredByFeature = new Map<string, Set<string>>();
  const desiredUsersByEmail = new Map<string, Record<string, unknown>>();
  LOGISTICS_FEATURE_KEYS.forEach((key) => {
    const feature = (config.features as Record<string, unknown>)?.[key] as Record<string, unknown> | undefined;
    const users = Array.isArray(feature?.users) ? feature.users as Record<string, unknown>[] : [];
    const keys = new Set<string>();
    users.forEach((row) => {
      const user = compactFeatureAccessUser(row);
      featureUserKeys(user).forEach((item) => keys.add(item));
      if (user.email) desiredUsersByEmail.set(normalizeAuthEmail(user.email), user);
    });
    desiredByFeature.set(key, keys);
  });

  const allPermissionRows = (permissionRows || []) as Record<string, unknown>[];
  const existingEmails = new Set(allPermissionRows.map((row) => normalizeAuthEmail(row.email)).filter(Boolean));
  let createdCount = 0;
  let changedCount = 0;
  for (const [email, user] of desiredUsersByEmail.entries()) {
    if (!email || existingEmails.has(email)) continue;
    const userKeys = featureUserKeys(user);
    const nextFeatures: Record<string, boolean> = {};
    LOGISTICS_FEATURE_KEYS.forEach((key) => {
      nextFeatures[key] = userKeys.some((item) => desiredByFeature.get(key)?.has(item));
    });
    const principal = await resolveExactPermissionPrincipal(ctx.serviceClient, email);
    if (principal.error) {
      return fail(409, 'An exact Auth user is required before feature permissions can be created', ctx.origin, { reason_code: principal.reasonCode });
    }
    const { error: upsertError } = await ctx.serviceClient
      .from('ll_user_permissions')
      .upsert(stripUndefined({
        user_id: principal.userId,
        email,
        staff_name: safeText(firstDefined(user.staff_name, staffNameForEmail(email))),
        organization: safeText(firstDefined(user.organization, organizationForEmail(email))),
        image_url: firstDefined(user.image_url, logisticsProfileImageUrl(email)),
        logistics_role: safeText(user.logistics_role) || 'Reader',
        managed_asset_codes: [],
        managed_asset_permissions: { read: true, create: false, update: false, delete: false },
        other_asset_permissions: { read: false, create: false, update: false, delete: false },
        can_ingest_weekly: false,
        account_status: 'active',
        feature_permissions: nextFeatures,
        profile_payload: { source: 'feature_access_update' },
        updated_at: new Date().toISOString(),
      }), { onConflict: 'email' });
    if (upsertError) return fail(500, 'Failed to create feature permission user', ctx.origin);
    createdCount += 1;
    existingEmails.add(email);
  }

  for (const row of allPermissionRows) {
    const rowEmail = normalizeAuthEmail(row.email);
    if (!isActivePermission(row) && !desiredUsersByEmail.has(rowEmail)) continue;
    const userKeys = featureUserKeys(compactFeatureAccessUser({
      email: row.email,
      staff_name: firstDefined(row.staff_name, staffNameForEmail(row.email)),
      organization: row.organization,
      image_url: row.image_url,
      logistics_role: row.logistics_role,
    }));
    const nextFeatures = { ...(row.feature_permissions as Record<string, unknown> || {}) };
    LOGISTICS_FEATURE_KEYS.forEach((key) => {
      nextFeatures[key] = userKeys.some((item) => desiredByFeature.get(key)?.has(item));
    });
    const currentFeatures = (row.feature_permissions as Record<string, unknown> || {});
    const featureChanged = [...LOGISTICS_FEATURE_KEYS].some((key) => Boolean(currentFeatures[key]) !== Boolean(nextFeatures[key]));
    const accountStatusChanged = desiredUsersByEmail.has(rowEmail) && safeText(row.account_status) !== 'active';
    if (!featureChanged && !accountStatusChanged) continue;
    let updateQuery = ctx.serviceClient
      .from('ll_user_permissions')
      .update(stripUndefined({
        feature_permissions: nextFeatures,
        account_status: desiredUsersByEmail.has(rowEmail) ? 'active' : undefined,
        updated_at: new Date().toISOString(),
      }));
    updateQuery = rowEmail ? updateQuery.ilike('email', rowEmail) : updateQuery.eq('user_id', row.user_id);
    const { data: updatedRows, error: updateError } = await updateQuery.select('user_id,email');
    if (updateError) return fail(500, 'Failed to save feature permissions', ctx.origin);
    if (!Array.isArray(updatedRows) || updatedRows.length < 1) {
      return fail(409, 'Feature permission user was not found during save readback', ctx.origin, { email: rowEmail || row.user_id });
    }
    changedCount += updatedRows.length;
  }

  const saved = await readFeatureAccessConfig(ctx);
  await auditOptional(ctx.serviceClient, ctx.user.id, 'feature-access/update', 200, { features: Object.keys(config.features as Record<string, unknown>) });
  return jsonResponse({ ok: true, data: saved, meta: { created_count: createdCount, changed_count: changedCount } }, 200, ctx.origin);
}

function normalizeMarketEmbedding(value: unknown) {
  const source = Array.isArray(value)
    ? value
    : typeof value === 'string'
      ? parseJsonValue(value, [])
      : [];
  if (!Array.isArray(source)) return undefined;
  const embedding = source.map((item) => Number(item)).filter((item) => Number.isFinite(item));
  return embedding.length === MARKET_EMBEDDING_DIM ? embedding : undefined;
}

type MarketStorageDocument = {
  document_id: string;
  source_hash: string;
  file_name: string;
  source_type: string;
  storage_bucket: string;
  storage_path: string;
  original_size_bytes: number | null;
  extracted_text_storage_bucket: string;
  extracted_text_storage_path: string;
  extraction_status: string;
  source_preservation_status: string;
  updated_at: string;
};

let marketStorageManifestCache: { expiresAt: number; documents: MarketStorageDocument[] } = {
  expiresAt: 0,
  documents: [],
};

function invalidateMarketStorageManifest() {
  marketStorageManifestCache = { expiresAt: 0, documents: [] };
}

function marketSourceTypeFromName(fileName: string) {
  const extension = fileExtension(fileName);
  if (extension === 'pdf' || extension === 'txt') return 'pdf';
  if (extension === 'xlsx' || extension === 'xls' || extension === 'csv') return 'xlsx';
  return extension || 'file';
}

async function listMarketStorageFiles(ctx: Context, prefix = '', depth = 0): Promise<Record<string, unknown>[]> {
  if (depth > 4) return [];
  const { data, error } = await ctx.serviceClient.storage.from(MARKET_SOURCE_BUCKET).list(prefix, {
    limit: 1000,
    sortBy: { column: 'name', order: 'asc' },
  });
  if (error) throw new Error(`Market source storage list failed: ${error.message}`);
  const files: Record<string, unknown>[] = [];
  for (const entry of (data || []) as unknown as Record<string, unknown>[]) {
    const name = safeText(entry.name);
    if (!name) continue;
    const path = prefix ? `${prefix}/${name}` : name;
    const metadata = entry.metadata && typeof entry.metadata === 'object' && !Array.isArray(entry.metadata)
      ? entry.metadata as Record<string, unknown>
      : null;
    if (metadata || entry.id) {
      files.push({ ...entry, path, metadata: metadata || {} });
      continue;
    }
    files.push(...await listMarketStorageFiles(ctx, path, depth + 1));
  }
  return files;
}

async function listMarketStorageDocuments(ctx: Context, force = false): Promise<MarketStorageDocument[]> {
  if (!force && marketStorageManifestCache.expiresAt > Date.now()) return marketStorageManifestCache.documents;
  const files = await listMarketStorageFiles(ctx);
  const byHash = new Map<string, { source?: Record<string, unknown>; extracted?: Record<string, unknown> }>();
  for (const file of files) {
    const path = safeText(file.path);
    const segments = path.split('/').filter(Boolean);
    if (segments.length < 3) continue;
    const sourceHash = segments[1];
    if (!/^[a-f0-9]{64}$/iu.test(sourceHash)) continue;
    const group = byHash.get(sourceHash) || {};
    if (segments.at(-1) === 'extracted-text.json') group.extracted = file;
    else group.source = file;
    byHash.set(sourceHash, group);
  }
  const documents = [...byHash.entries()]
    .filter(([, group]) => group.source || group.extracted)
    .map(([sourceHash, group]) => {
      const sourcePath = safeText(group.source?.path);
      const extractedPath = safeText(group.extracted?.path);
      const sourceMetadata = group.source?.metadata && typeof group.source.metadata === 'object'
        ? group.source.metadata as Record<string, unknown>
        : {};
      const fileName = sourcePath.split('/').at(-1) || `${sourceHash.slice(0, 12)}.source`;
      return {
        document_id: sourceHash,
        source_hash: sourceHash,
        file_name: fileName,
        source_type: marketSourceTypeFromName(fileName),
        storage_bucket: MARKET_SOURCE_BUCKET,
        storage_path: sourcePath,
        original_size_bytes: numberValue(sourceMetadata.size),
        extracted_text_storage_bucket: extractedPath ? MARKET_SOURCE_BUCKET : '',
        extracted_text_storage_path: extractedPath,
        extraction_status: extractedPath ? 'ready' : 'uploaded_pending_extraction',
        source_preservation_status: sourcePath ? 'stored' : 'metadata_only',
        updated_at: safeText(firstDefined(group.source?.updated_at, group.source?.created_at, group.extracted?.updated_at, group.extracted?.created_at)),
      } satisfies MarketStorageDocument;
    })
    .sort((a, b) => b.updated_at.localeCompare(a.updated_at));
  marketStorageManifestCache = { expiresAt: Date.now() + 60_000, documents };
  return documents;
}

async function readMarketStoragePayload(ctx: Context, document: MarketStorageDocument) {
  if (!document.extracted_text_storage_path) return null;
  const { data, error } = await ctx.serviceClient.storage
    .from(document.extracted_text_storage_bucket || MARKET_SOURCE_BUCKET)
    .download(document.extracted_text_storage_path);
  if (error || !data) return null;
  try {
    return parseJsonValue(await data.text(), null) as Record<string, unknown> | null;
  } catch {
    return null;
  }
}

function marketStorageTextChunks(text: string, maxLength = 1400) {
  const paragraphs = text.split(/\n{2,}/gu).map((item) => item.trim()).filter(Boolean);
  const chunks: string[] = [];
  let current = '';
  for (const paragraph of paragraphs) {
    if (current && current.length + paragraph.length + 2 > maxLength) {
      chunks.push(current);
      current = '';
    }
    current = current ? `${current}\n\n${paragraph}` : paragraph;
  }
  if (current) chunks.push(current);
  if (!chunks.length && text.trim()) chunks.push(text.trim().slice(0, maxLength));
  return chunks.slice(0, 500);
}

async function loadMarketStorageSearchRows(ctx: Context) {
  const documents = await listMarketStorageDocuments(ctx);
  const payloads = await Promise.all(documents.map(async (document) => ({
    document,
    payload: await readMarketStoragePayload(ctx, document),
  })));
  const facts: Record<string, unknown>[] = [];
  const chunks: Record<string, unknown>[] = [];
  for (const { document, payload } of payloads) {
    if (!payload) continue;
    const payloadFacts = Array.isArray(payload.facts) ? payload.facts as Record<string, unknown>[] : [];
    const payloadChunks = Array.isArray(payload.chunks) ? payload.chunks as Record<string, unknown>[] : [];
    const text = safeText(payload.text || payload.extracted_text);
    payloadFacts.forEach((row, index) => facts.push({
      ...row,
      source_hash: document.source_hash,
      fact_key: safeText(row.fact_key) || `${document.source_hash}:fact:${index}`,
      extraction_status: 'ready',
    }));
    if (payloadChunks.length) {
      payloadChunks.forEach((row, index) => chunks.push({
        ...row,
        source_hash: document.source_hash,
        chunk_key: safeText(row.chunk_key) || `${document.source_hash}:chunk:${index}`,
        content: safeText(row.content),
        extraction_status: 'ready',
      }));
    } else {
      marketStorageTextChunks(text).forEach((content, index) => chunks.push({
        source_hash: document.source_hash,
        chunk_key: `${document.source_hash}:text:${index}`,
        chunk_type: 'stored_extracted_text',
        content,
        extraction_status: 'ready',
        source_locator: { storage_path: document.extracted_text_storage_path, chunk_index: index },
      }));
    }
  }
  return { documents, facts, chunks };
}

async function callMarketDocsUpload(ctx: Context, formData: FormData | null) {
  if (!canManageFeatureAccess(ctx)) return fail(403, 'Market document upload is limited to Planning Center users', ctx.origin);
  if (!checkRateLimit(ctx.user.id, 'market-docs/upload', 12, 60_000)) return fail(429, 'Rate limit exceeded', ctx.origin);
  if (!formData) return fail(400, 'Multipart form data is required', ctx.origin);
  const payloadEntry = formData.get('payload');
  const uploadPayload = typeof payloadEntry === 'string' && payloadEntry.trim()
    ? parseJsonValue(payloadEntry, {}) as Record<string, unknown>
    : {};
  const uploadOrigin = safeText(uploadPayload.upload_origin || uploadPayload.uploadOrigin, 'workspace_ui');
  const sourceDomain = safeText(uploadPayload.source_domain || uploadPayload.sourceDomain, 'market_documents');
  const file = formData.get('file');
  if (!(file instanceof File)) return fail(400, 'file is required', ctx.origin);
  const originalName = safeStorageFileName(file.name || 'market-source');
  const extension = fileExtension(originalName);
  if (!MARKET_SOURCE_ALLOWED_EXTENSIONS.has(extension)) return fail(400, 'Only PDF, Excel, and text files are supported', ctx.origin);
  if (file.size <= 0) return fail(400, 'Uploaded file is empty', ctx.origin);
  if (file.size > MARKET_SOURCE_MAX_BYTES) return fail(413, 'Uploaded file is too large', ctx.origin);
  const bytes = new Uint8Array(await file.arrayBuffer());
  const sourceHash = await sha256Bytes(bytes);
  const storageObjectName = safeStorageObjectName(originalName, extension);
  const storagePath = `${sourceHash.slice(0, 2)}/${sourceHash}/${storageObjectName}`;
  const { error: uploadError } = await ctx.serviceClient
    .storage
    .from(MARKET_SOURCE_BUCKET)
    .upload(storagePath, bytes, {
      contentType: file.type || (extension === 'pdf' ? 'application/pdf' : 'application/octet-stream'),
      upsert: true,
    });
  if (uploadError) {
    await auditOptional(ctx.serviceClient, ctx.user.id, 'market-docs/upload', 500, { file_name: originalName, error: uploadError.message });
    return fail(500, 'Market source file upload failed', ctx.origin, { error: uploadError.message });
  }
  invalidateMarketStorageManifest();
  const documents = await listMarketStorageDocuments(ctx, true);
  const savedDoc = documents.find((document) => document.source_hash === sourceHash) || {
    document_id: sourceHash,
    source_hash: sourceHash,
    file_name: originalName,
    source_type: marketSourceTypeFromName(originalName),
    storage_bucket: MARKET_SOURCE_BUCKET,
    storage_path: storagePath,
    original_size_bytes: file.size,
    extracted_text_storage_bucket: '',
    extracted_text_storage_path: '',
    extraction_status: 'uploaded_pending_extraction',
    source_preservation_status: 'stored',
    updated_at: new Date().toISOString(),
  };
  await audit(ctx.serviceClient, ctx.user.id, 'market-docs/upload', 200, {
    document_id: sourceHash,
    file_name: originalName,
    source_hash: sourceHash,
    storage_path: storagePath,
    original_size_bytes: file.size,
    upload_origin: uploadOrigin,
    source_domain: sourceDomain,
  });
  return jsonResponse({
    ok: true,
    data: {
      document: savedDoc,
      source_hash: sourceHash,
      storage_bucket: MARKET_SOURCE_BUCKET,
      storage_path: storagePath,
      original_size_bytes: file.size,
      message: '원본 파일은 Supabase Storage에 보관되었습니다. 검색용 텍스트/표 데이터는 추출 처리 후 챗봇 근거로 사용됩니다.',
    },
  }, 200, ctx.origin);
}

async function callMarketDocsIngest(ctx: Context, payload: Record<string, unknown>) {
  if (!canManageFeatureAccess(ctx)) return fail(403, 'Market document ingest is limited to Planning Center users', ctx.origin);
  if (!checkRateLimit(ctx.user.id, 'market-docs/ingest', 90, 60_000)) return fail(429, 'Rate limit exceeded', ctx.origin);
  const documentInput = payload.document && typeof payload.document === 'object' && !Array.isArray(payload.document)
    ? payload.document as Record<string, unknown>
    : payload;
  const sourceHash = safeText(documentInput.source_hash);
  if (!sourceHash || !safeText(documentInput.file_name)) return fail(400, 'source_hash and file_name are required', ctx.origin);
  const chunksInput = Array.isArray(payload.chunks) ? payload.chunks as Record<string, unknown>[] : [];
  const factsInput = Array.isArray(payload.facts) ? payload.facts as Record<string, unknown>[] : [];
  const extractedText = safeText(payload.extracted_text);
  let extractedTextStoragePath = safeText(documentInput.extracted_text_storage_path);
  let extractedTextStorageBucket = safeText(documentInput.extracted_text_storage_bucket);
  if (extractedText) {
    const extractedTextHash = await sha256Text(extractedText);
    const extractedPayload = JSON.stringify({
      source_hash: sourceHash,
      document: documentInput,
      extracted_text_hash: extractedTextHash,
      extracted_char_count: extractedText.length,
      extracted_at: new Date().toISOString(),
      text: extractedText,
      chunks: chunksInput,
      facts: factsInput,
    });
    extractedTextStorageBucket = MARKET_SOURCE_BUCKET;
    extractedTextStoragePath = `${sourceHash.slice(0, 2)}/${sourceHash}/extracted-text.json`;
    const { error: extractedUploadError } = await ctx.serviceClient
      .storage
      .from(MARKET_SOURCE_BUCKET)
      .upload(extractedTextStoragePath, new TextEncoder().encode(extractedPayload), {
        contentType: 'text/plain',
        upsert: true,
      });
    if (extractedUploadError) {
      return fail(500, 'Market extracted text upload failed', ctx.origin, { error: extractedUploadError.message });
    }
  }
  if (!extractedTextStoragePath) {
    extractedTextStorageBucket = MARKET_SOURCE_BUCKET;
    extractedTextStoragePath = `${sourceHash.slice(0, 2)}/${sourceHash}/extracted-text.json`;
    const extractedPayload = JSON.stringify({
      source_hash: sourceHash,
      document: documentInput,
      extracted_text_hash: '',
      extracted_char_count: 0,
      extracted_at: new Date().toISOString(),
      text: '',
      chunks: chunksInput,
      facts: factsInput,
    });
    const { error: extractedUploadError } = await ctx.serviceClient.storage
      .from(MARKET_SOURCE_BUCKET)
      .upload(extractedTextStoragePath, new TextEncoder().encode(extractedPayload), {
        contentType: 'application/json',
        upsert: true,
      });
    if (extractedUploadError) {
      return fail(500, 'Market extracted text upload failed', ctx.origin, { error: extractedUploadError.message });
    }
  }
  invalidateMarketStorageManifest();
  await audit(ctx.serviceClient, ctx.user.id, 'market-docs/ingest', 200, {
    file_name: safeText(documentInput.file_name),
    source_hash: sourceHash.slice(0, 16),
    chunks: chunksInput.length,
    facts: factsInput.length,
    storage_bucket: extractedTextStorageBucket,
    storage_path: extractedTextStoragePath,
  });
  return jsonResponse({
    ok: true,
    data: {
      file_name: safeText(documentInput.file_name),
      document_id: sourceHash,
      chunks_written: chunksInput.length,
      facts_written: factsInput.length,
      replace_existing: payload.replace_existing !== false,
      retrieval_mode: 'storage_lexical',
      storage_bucket: extractedTextStorageBucket,
      storage_path: extractedTextStoragePath,
    },
  }, 200, ctx.origin);

}

async function callMarketDocsStatus(ctx: Context) {
  if (!hasUserFeaturePermission(ctx.permission, 'market_research') && !canManageFeatureAccess(ctx)) return fail(403, 'Market research permission is required', ctx.origin);
  const storageRows = await loadMarketStorageSearchRows(ctx);
  const documents = storageRows.documents.map((row) => stripUndefined({
    document_id: row.document_id,
    source_hash: row.source_hash,
    file_name: row.file_name,
    source_type: row.source_type,
    extraction_status: row.extraction_status,
    source_preservation_status: row.source_preservation_status,
    original_size_bytes: row.original_size_bytes,
    storage_bucket: row.storage_bucket,
    storage_path: row.storage_path,
    extracted_text_storage_bucket: row.extracted_text_storage_bucket,
    extracted_text_storage_path: row.extracted_text_storage_path,
    storage_preserved: Boolean(row.storage_path),
    extracted_text_preserved: Boolean(row.extracted_text_storage_path),
    updated_at: row.updated_at,
  }));
  return jsonResponse({
    ok: true,
    data: {
      documents: documents.length,
      chunks: storageRows.chunks.length,
      facts: storageRows.facts.length,
      preserved_documents: documents.filter((row) => (row as Record<string, unknown>).storage_preserved).length,
      preserved_extracted_texts: documents.filter((row) => (row as Record<string, unknown>).extracted_text_preserved).length,
      recent_documents: documents.slice(0, 50),
      retrieval_mode: 'storage_lexical',
      retrieval_status: 'storage_lexical_ready',
    },
  }, 200, ctx.origin);

}

async function callMarketDocsSearch(ctx: Context, payload: Record<string, unknown>) {
  const question = safeText(firstDefined(payload.question, payload.query, payload.search));
  if (!question) return fail(400, 'question is required', ctx.origin);
  try {
    const result = await searchMarketMaterials(ctx, question, Math.min(20, Math.max(3, Number(payload.limit || 8) || 8)));
    if (!result.allowed) return fail(403, 'Market research permission is required', ctx.origin);
    if (!result.retrieval_ok) {
      const status = result.retrieval_status === 'sector_storage_lexical_failed' ? 502 : 404;
      await auditOptional(ctx.serviceClient, ctx.user.id, 'market-docs/search', status, {
        question,
        retrieval_status: result.retrieval_status,
        source_status: result.source_status,
      });
      return fail(
        status,
        status === 502 ? 'Market document search sources are unavailable' : 'No market materials matched the search',
        ctx.origin,
        { retrieval_status: result.retrieval_status, source_status: result.source_status },
      );
    }
    await auditOptional(ctx.serviceClient, ctx.user.id, 'market-docs/search', 200, { question, evidence_count: result.evidence.length });
    return jsonResponse({ ok: true, data: { evidence: result.evidence, terms: result.terms, fact_count: result.facts.length, chunk_count: result.chunks.length, retrieval_status: result.retrieval_status, source_status: result.source_status } }, 200, ctx.origin);
  } catch (error) {
    const message = safeProviderError(error);
    await auditOptional(ctx.serviceClient, ctx.user.id, 'market-docs/search', 500, { question, error: message });
    return fail(500, 'Market document search failed', ctx.origin, { error: message });
  }
}

async function callMarketDocsEmbed(ctx: Context, _payload: Record<string, unknown>) {
  if (!canManageFeatureAccess(ctx)) return fail(403, 'Market embedding generation is limited to Planning Center users', ctx.origin);
  if (!checkRateLimit(ctx.user.id, 'market-docs/embed', 20, 60_000)) return fail(429, 'Rate limit exceeded', ctx.origin);
  const documents = await listMarketStorageDocuments(ctx);
  const output = {
    mode: 'storage_lexical',
    status: 'not_applicable',
    embedding_required: false,
    preserved_documents: documents.filter((row) => Boolean(row.storage_path)).length,
    searchable_documents: documents.filter((row) => Boolean(row.extracted_text_storage_path)).length,
    message: 'Market research retrieval uses preserved extracted text with lexical ranking; no relational embedding index is configured.',
  };
  await auditOptional(ctx.serviceClient, ctx.user.id, 'market-docs/embed', 200, output);
  return jsonResponse({ ok: true, data: output }, 200, ctx.origin);

}

function filterWorkPlatformTaskRows(ctx: Context, rows: Record<string, unknown>[]) {
  const organization = String(ctx.permission?.organization || '');
  return rows.filter((row) => {
    if (row.created_by === ctx.user.id) return true;
    if (canReadRelatedAsset(ctx, row.related_asset_id)) return true;
    return Boolean(String(row.organization || '') === organization && !row.related_asset_id);
  });
}

function explicitBoardLegacyScope(row: Record<string, unknown>) {
  const metadata = row.board_metadata && typeof row.board_metadata === 'object' && !Array.isArray(row.board_metadata)
    ? row.board_metadata as Record<string, unknown>
    : (row.metadata && typeof row.metadata === 'object' && !Array.isArray(row.metadata) ? row.metadata as Record<string, unknown> : {});
  return safeText(firstDefined(row.legacy_scope, row.visibility_scope, metadata.legacy_scope, metadata.visibility_scope, metadata.access_scope)).toLowerCase();
}

async function filterWorkPlatformBoardRows(ctx: Context, rows: Record<string, unknown>[]) {
  const permitted = await Promise.all(rows.map(async (row) => {
    const relatedAssetId = safeText(row.related_asset_id);
    if (relatedAssetId) {
      return (await evaluateCanonicalAssetPermission(ctx, 'read', relatedAssetId)).allowed ? row : null;
    }
    const legacyScope = explicitBoardLegacyScope(row);
    if (legacyScope === 'global') return row;
    if (legacyScope === 'self' && safeText(row.created_by) === ctx.user.id) return row;
    return null;
  }));
  return permitted.filter((row): row is Record<string, unknown> => row !== null);
}

function hasPermissionRow(ctx: Context) {
  return isActivePermission(ctx.permission);
}

function allReadableAssetsAllowed(ctx: Context) {
  const managedRefs = managedAssetCodes(ctx.permission);
  return permissionFlag(ctx.permission, 'other_asset_permissions', 'read')
    && (!managedRefs.length || permissionFlag(ctx.permission, 'managed_asset_permissions', 'read'));
}

function matchesManagedAsset(ctx: Context, row: Record<string, unknown>) {
  const managed = new Set(managedAssetCodes(ctx.permission).map((item) => String(item).trim()).filter(Boolean));
  return managed.has(String(row.asset_id || ''))
    || managed.has(String(row.asset_code || ''))
    || managed.has(String(row.asset_name || ''));
}

function dashboardAssetDispositionStatus(row: Record<string, unknown>) {
  const status = [row.asset_status, row.disposition_status, row.review_status, row.status]
    .map((value) => safeText(value))
    .filter(Boolean)
    .join(' ');
  const assetName = safeText(row.asset_name);
  if (/매각|sold|disposed|archived/i.test(status)) return 'sold';
  if (/안성\s*성은|성은\s*물류센터/iu.test(assetName)) return 'sold';
  if (/리뷰|검토|review/i.test(status)) return 'review';
  return status ? 'active' : 'active';
}

function isDashboardVisibleAsset(row: Record<string, unknown>) {
  return dashboardAssetDispositionStatus(row) !== 'sold';
}

async function listReadableAssetsForDashboard(ctx: Context) {
  if (!hasPermissionRow(ctx)) return { rows: [], errorResponse: fail(403, 'No logistics permission row found', ctx.origin) };
  const { data, error } = await ctx.serviceClient
    .from('ll_assets')
    .select('*')
    .order('asset_name', { ascending: true })
    .limit(500);
  if (error) return { rows: [], errorResponse: fail(500, 'Failed to read assets', ctx.origin) };
  const rows = ((data || []) as Record<string, unknown>[]).filter(isDashboardVisibleAsset);
  const capabilityResult = await assetCapabilitiesForProfile(ctx);
  if (capabilityResult.error) return { rows: [], errorResponse: fail(500, 'Failed to read asset capabilities', ctx.origin) };
  return {
    rows: rows.filter((row) => capabilityResult.capabilities[safeText(row.asset_id)]?.read === true),
    errorResponse: null,
  };
}

function currentKstMonthEndDate() {
  const now = new Date();
  const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
  const year = kst.getUTCFullYear();
  const month = kst.getUTCMonth() + 1;
  const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
  return `${year}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;
}

function currentKstDate() {
  const now = new Date();
  const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000));
  return `${kst.getUTCFullYear()}-${String(kst.getUTCMonth() + 1).padStart(2, '0')}-${String(kst.getUTCDate()).padStart(2, '0')}`;
}

function dashboardBasisDate(payload: Record<string, unknown>) {
  const fallbackBasisDate = currentKstMonthEndDate();
  const basisDate = safeText(firstDefined(payload.basis_date, payload.basisDate, fallbackBasisDate));
  return /^\d{4}-\d{2}-\d{2}$/u.test(basisDate) ? basisDate : fallbackBasisDate;
}

async function dashboardScope(ctx: Context, assets: Record<string, unknown>[]) {
  const readableAssetIds = assets.map((row) => String(row.asset_id || '')).filter(Boolean).sort();
  return {
    role: ctx.role,
    readable_asset_ids: readableAssetIds,
    scope_hash: await sha256Text(JSON.stringify({
      user_id: ctx.user.id,
      role: ctx.role,
      readable_asset_ids: readableAssetIds,
    })),
  };
}

function dashboardEvidence(entries: Record<string, unknown>[]) {
  return {
    tables: entries.map((entry) => stripUndefined(entry)),
    source_cells: [],
  };
}

function sumNumber(rows: Record<string, unknown>[], key: string) {
  return rows.reduce((sum, row) => {
    const value = Number(row[key] || 0);
    return Number.isFinite(value) ? sum + value : sum;
  }, 0);
}

function isCurrentDashboardLeaseSpace(row: Record<string, unknown>) {
  const status = normalizeText(row.contract_status).trim().toLowerCase();
  if (!status) return false;
  if (['active', 'y', 'yes', 'current', 'in_force', 'ongoing'].includes(status)) return true;
  if (['inactive', 'n', 'no', 'false', '0', 'vacant', 'vacancy', 'empty', 'placeholder'].includes(status)) return false;
  if (
    status.includes('superseded')
    || status.includes('inactive')
    || status.includes('expired')
    || status.includes('terminated')
    || status.includes('cancelled')
    || status.includes('종료')
    || status.includes('해지')
    || status.includes('만료')
  ) return false;
  return true;
}

function currentDashboardLeaseSpaces(rows: Record<string, unknown>[]) {
  return rows.filter(isCurrentDashboardLeaseSpace);
}

function parseDateMs(value: unknown) {
  const text = normalizeText(value);
  if (!text) return null;
  const parsed = Date.parse(text);
  return Number.isFinite(parsed) ? parsed : null;
}

function isCurrentOrFutureRentHistoryCell(cell: ReturnType<typeof normalizeEditCells>[number], row: Record<string, unknown>) {
  if (cell.targetTable !== 'public.ll_rent_history') return true;
  if (row.is_latest === true || normalizeText(row.is_latest).toLowerCase() === 'true') return true;
  const basisMs = parseDateMs(firstDefined(row.basis_date, row.basisDate, row.effective_date, row.effectiveDate));
  if (basisMs === null) return true;
  const today = new Date();
  const monthStartUtc = Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 1);
  return basisMs >= monthStartUtc;
}

function dashboardNumber(value: unknown) {
  const numeric = Number(String(value ?? '').replace(/,/gu, '').replace(/[^\d.-]/gu, ''));
  return Number.isFinite(numeric) ? numeric : 0;
}

function dashboardAreaKey(value: unknown) {
  const numeric = dashboardNumber(value);
  return numeric ? String(Math.round(numeric)) : '';
}

function dashboardRentHistoryComponentKey(row: Record<string, unknown>) {
  return [
    row.asset_id,
    row.tenant_id,
    firstDefined(row.source_contract_lease_space_id, row.lease_space_id),
    row.floor_label,
    row.detail_area_label,
    row.temperature_type,
    dashboardAreaKey(row.leased_area_sqm),
    dashboardAreaKey(row.exclusive_area_sqm),
  ].map((value) => normalizeText(value)).join('|');
}

function dashboardRentHistoryDateValue(row: Record<string, unknown>) {
  const text = safeText(row.effective_date);
  if (/^\d{4}-\d{2}-\d{2}$/u.test(text)) return text;
  return '';
}

function dashboardRentHistoryCost(row: Record<string, unknown>) {
  return dashboardNumber(row.monthly_rent_total) + dashboardNumber(row.monthly_mf_total);
}

function selectLatestDashboardRentHistoryRows(rows: Record<string, unknown>[], basisDate = '') {
  const latestByComponent = new Map<string, Record<string, unknown>>();
  const basisValue = dashboardRentHistoryDateValue({ effective_date: basisDate });
  for (const row of rows) {
    const key = dashboardRentHistoryComponentKey(row);
    if (!key.trim()) continue;
    const date = dashboardRentHistoryDateValue(row);
    if (basisValue && date && date > basisValue) continue;
    const previous = latestByComponent.get(key);
    if (!previous) {
      latestByComponent.set(key, row);
      continue;
    }
    const previousDate = dashboardRentHistoryDateValue(previous);
    if (date > previousDate) {
      latestByComponent.set(key, row);
      continue;
    }
    if (date === previousDate) {
      const cost = dashboardRentHistoryCost(row);
      const previousCost = dashboardRentHistoryCost(previous);
      if (
        cost > previousCost
        || (cost === previousCost && safeText(row.source_sheet_row_id) > safeText(previous.source_sheet_row_id))
      ) {
        latestByComponent.set(key, row);
      }
    }
  }
  return [...latestByComponent.values()];
}

function applyLatestRentHistoryAmountsToLeaseSpaces(leaseSpaces: Record<string, unknown>[], rentHistory: Record<string, unknown>[], basisDate = ''): Record<string, unknown>[] {
  const latestHistoryRows = selectLatestDashboardRentHistoryRows(rentHistory, basisDate);
  const amountByLeaseSpace = new Map<string, { rent: number; mf: number; cost: number }>();
  for (const row of latestHistoryRows) {
    const leaseSpaceId = safeText(firstDefined(row.source_contract_lease_space_id, row.lease_space_id));
    if (!leaseSpaceId) continue;
    const previous = amountByLeaseSpace.get(leaseSpaceId) || { rent: 0, mf: 0, cost: 0 };
    const rent = dashboardNumber(row.monthly_rent_total);
    const mf = dashboardNumber(row.monthly_mf_total);
    previous.rent += rent;
    previous.mf += mf;
    previous.cost += rent + mf;
    amountByLeaseSpace.set(leaseSpaceId, previous);
  }
  return leaseSpaces.map((row) => {
    const leaseSpaceId = safeText(row.lease_space_id);
    const amount = amountByLeaseSpace.get(leaseSpaceId);
    if (!amount) return row;
    const leasedAreaPy = dashboardNumber(row.leased_area_sqm) * 0.3025;
    return stripUndefined({
      ...row,
      current_monthly_rent_total: amount.rent,
      current_monthly_mf_total: amount.mf,
      current_monthly_cost_total: amount.cost,
      e_noc: leasedAreaPy > 0 ? Math.round((amount.cost / leasedAreaPy) * 100) / 100 : row.e_noc,
      review_status: firstDefined(row.review_status, 'dashboard_latest_history_applied'),
    }) as Record<string, unknown>;
  });
}

