type NewsCollectorItem = {
  dedupe_key: string;
  canonical_url: string;
  original_url: string;
  title: string;
  publisher: string;
  published_at: string;
  summary: string;
  importance_score: number;
  matched_keywords: string[];
  source_name: string;
  payload: Record<string, unknown>;
};

class NewsRunCollectionError extends Error {
  status: 409 | 502;
  details: Record<string, unknown>;

  constructor(status: 409 | 502, message: string, details: Record<string, unknown> = {}) {
    super(message);
    this.name = 'NewsRunCollectionError';
    this.status = status;
    this.details = details;
  }
}

function newsStripHtml(value: unknown) {
  return String(value || '')
    .replace(/<!\[CDATA\[(.*?)\]\]>/gsu, '$1')
    .replace(/<[^>]+>/gu, '')
    .replace(/&quot;/gu, '"')
    .replace(/&#39;/gu, "'")
    .replace(/&amp;/gu, '&')
    .replace(/&lt;/gu, '<')
    .replace(/&gt;/gu, '>')
    .replace(/\s+/gu, ' ')
    .trim();
}

function newsXmlTag(source: unknown, tag: string) {
  const match = String(source || '').match(new RegExp(`<${tag}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${tag}>`, 'iu'));
  return match ? newsStripHtml(match[1]) : '';
}

function newsParseRssItems(xml: string, sourceName: string, query: string) {
  return [...String(xml || '').matchAll(/<item\b[^>]*>([\s\S]*?)<\/item>/giu)]
    .map((match) => {
      const item = match[1];
      return {
        title: newsXmlTag(item, 'title'),
        description: newsXmlTag(item, 'description'),
        pubDate: newsXmlTag(item, 'pubDate'),
        link: newsXmlTag(item, 'link'),
        publisher: newsXmlTag(item, 'source'),
        source_name: sourceName,
        query,
      };
    })
    .filter((item) => item.title && item.link);
}

function newsCanonicalUrl(value: unknown) {
  try {
    const url = new URL(String(value || ''));
    ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'fbclid', 'gclid'].forEach((key) => url.searchParams.delete(key));
    url.hash = '';
    return url.toString();
  } catch {
    return safeText(value);
  }
}

function newsNormalizeTitle(value: unknown) {
  return newsStripHtml(value)
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, '')
    .slice(0, 120);
}

function newsPublisher(item: Record<string, unknown>) {
  const direct = safeText(item.publisher);
  if (direct) return direct;
  try {
    return new URL(String(item.link || '')).hostname.replace(/^www\./u, '');
  } catch {
    return '';
  }
}

function newsEscapeRegExp(value: unknown) {
  return String(value || '').replace(/[.*+?^${}()|[\]\\]/gu, '\\$&');
}

function newsCleanTitle(title: unknown, publisher: unknown = '') {
  let out = newsStripHtml(title);
  const publisherVariants = [
    safeText(publisher),
    safeText(publisher).replace(/\s+/gu, ''),
    safeText(publisher).replace(/뉴스$/u, ''),
  ].filter(Boolean);
  for (const variant of publisherVariants) {
    const escaped = newsEscapeRegExp(variant);
    out = out
      .replace(new RegExp(`\\s*[-|–—·ㆍ:]\\s*${escaped}\\s*$`, 'iu'), '')
      .replace(new RegExp(`^${escaped}\\s*[-|–—·ㆍ:]\\s*`, 'iu'), '');
  }
  return out
    .replace(/\s*[-|–—·ㆍ:]\s*(네이버뉴스|Google News|Bing News)\s*$/iu, '')
    .replace(/^\s*(?:\[중요\]|중요[:：-])\s*/iu, '')
    .replace(/\s+/gu, ' ')
    .trim();
}

function newsMatchTerms(text: string, terms: string[]) {
  const lower = text.toLowerCase();
  return terms.filter((term) => lower.includes(term.toLowerCase()));
}

function newsCompanyForText(text: string) {
  const lower = text.toLowerCase();
  return NEWS_MAJOR_COMPANIES.find((company) => company.terms.some((term) => lower.includes(term.toLowerCase()))) || null;
}

function newsScore(item: { title: string; summary: string }) {
  const combined = `${item.title} ${item.summary}`;
  const logisticsMatches = newsMatchTerms(combined, NEWS_LOGISTICS_CONTEXT_TERMS);
  const dealMatches = newsMatchTerms(combined, NEWS_MARKET_DEAL_TERMS);
  const leaseMatches = newsMatchTerms(combined, NEWS_LEASE_MARKET_TERMS);
  const supplyMatches = newsMatchTerms(combined, NEWS_SUPPLY_DEVELOPMENT_TERMS);
  const reportMatches = newsMatchTerms(combined, NEWS_MARKET_REPORT_TERMS);
  const company = newsCompanyForText(combined);
  const hasLogisticsContext = logisticsMatches.length > 0;
  const hasMarketSignal = dealMatches.length || leaseMatches.length || reportMatches.length;
  const hasSupplySignal = supplyMatches.length;
  const companyLogisticsSignal = company && /물류|센터|창고|풀필먼트|허브|택배|배송|터미널|fulfillment/iu.test(combined);
  const companyBusinessSignal = company && newsMatchTerms(combined, NEWS_COMPANY_BUSINESS_TERMS).length > 0;
  if ((!hasLogisticsContext || (!hasMarketSignal && !hasSupplySignal)) && !companyLogisticsSignal && !companyBusinessSignal) {
    return { score: 0, matched: [], category: 'noise', company: null };
  }
  let category = 'major_company';
  if (dealMatches.length || reportMatches.length) category = 'market_deal';
  else if (leaseMatches.length) category = 'lease_market';
  else if (supplyMatches.length) category = 'supply_development';
  else if (!company) category = 'other';
  const matched = [...new Set([
    ...logisticsMatches,
    ...dealMatches,
    ...leaseMatches,
    ...supplyMatches,
    ...reportMatches,
    ...(company ? [company.label] : []),
  ])];
  const score = (logisticsMatches.length * 1.5)
    + (dealMatches.length * 3)
    + (leaseMatches.length * 3)
    + (supplyMatches.length * 1.5)
    + (reportMatches.length * 3)
    + (company ? 2 : 0)
    + (companyBusinessSignal ? 1 : 0);
  return { score, matched, category, company };
}

function newsTitleTokens(value: unknown) {
  return [...new Set(newsStripHtml(value).toLowerCase().match(/[\p{L}\p{N}]{2,}/gu) || [])]
    .filter((token) => !['단독', '종합', '속보', '포토', '영상', '뉴스', '피벗', '인사이트'].includes(token));
}

function newsTitleSimilarity(left: unknown, right: unknown) {
  const a = newsTitleTokens(left);
  const b = newsTitleTokens(right);
  if (!a.length || !b.length) return 0;
  const bSet = new Set(b);
  const overlap = a.filter((token) => bSet.has(token)).length;
  return overlap / Math.min(a.length, b.length);
}

function newsStoryClusterKey(value: unknown) {
  const normalized = newsNormalizeTitle(value);
  const text = newsStripHtml(value).toLowerCase();
  const hasAny = (terms: string[]) => terms.some((term) => text.includes(term.toLowerCase()));
  if (
    hasAny(['네이버', 'naver'])
    && hasAny(['물류', '물류센터', '배송', '직배송', '커머스', '거점', '풀필먼트'])
    && hasAny(['쿠팡', '배민', '투자', '인수', '추격', '맞대결'])
  ) return 'story:naver-logistics-commerce';
  if (normalized.includes('캠퍼스크루') || (normalized.includes('쿠팡풀필먼트') && normalized.includes('인증'))) return 'story:coupang-campuscrew';
  if (normalized.includes('롱탄') && normalized.includes('물류센터')) return 'story:long-thanh-logistics-center';
  if (normalized.includes('휴머노이드') && normalized.includes('물류센터')) return 'story:humanoid-logistics-center';
  if (normalized.includes('lx판토스') && normalized.includes('물류센터')) return 'story:lx-pantos-logistics-center';
  return '';
}

function newsRemoveNearDuplicateStories(items: NewsCollectorItem[]) {
  const selected: NewsCollectorItem[] = [];
  const clusters = new Set<string>();
  for (const item of items) {
    const cluster = newsStoryClusterKey(item.title);
    if (cluster && clusters.has(cluster)) continue;
    if (selected.some((existing) => newsTitleSimilarity(existing.title, item.title) >= 0.62)) continue;
    if (cluster) clusters.add(cluster);
    selected.push(item);
  }
  return selected;
}

function newsCompanyKeyForItem(item: NewsCollectorItem) {
  return safeText(item.payload?.company_key)
    || safeText(newsCompanyForText(`${item.title || ''} ${item.summary || ''}`)?.key);
}

function newsSelectBalancedItems(items: NewsCollectorItem[], limit = 10) {
  const sorted = newsRemoveNearDuplicateStories(items).sort(
    (a, b) => Number(b.importance_score) - Number(a.importance_score) || Date.parse(b.published_at) - Date.parse(a.published_at),
  );
  const selected: NewsCollectorItem[] = [];
  const selectedKeys = new Set<string>();
  const categoryCounts: Record<string, number> = {};
  const companyCounts: Record<string, number> = {};
  const canAdd = (item: NewsCollectorItem, enforceCategoryTarget: boolean) => {
    if (!item || selectedKeys.has(item.dedupe_key)) return false;
    const category = safeText(item.payload?.category || 'other');
    const companyKey = newsCompanyKeyForItem(item);
    if (companyKey && (companyCounts[companyKey] || 0) >= NEWS_MAX_ITEMS_PER_COMPANY) return false;
    if (category === 'major_company' && (categoryCounts.major_company || 0) >= NEWS_MAX_MAJOR_COMPANY_ONLY_ITEMS) return false;
    if (enforceCategoryTarget && NEWS_CATEGORY_TARGETS[category] && (categoryCounts[category] || 0) >= NEWS_CATEGORY_TARGETS[category]) return false;
    return true;
  };
  const add = (item: NewsCollectorItem, enforceCategoryTarget = false) => {
    if (!canAdd(item, enforceCategoryTarget)) return false;
    const category = safeText(item.payload?.category || 'other');
    const companyKey = newsCompanyKeyForItem(item);
    selected.push(item);
    selectedKeys.add(item.dedupe_key);
    categoryCounts[category] = (categoryCounts[category] || 0) + 1;
    if (companyKey) companyCounts[companyKey] = (companyCounts[companyKey] || 0) + 1;
    return selected.length >= limit;
  };
  for (const category of NEWS_CATEGORY_ORDER) {
    for (const item of sorted.filter((row) => safeText(row.payload?.category || 'other') === category)) {
      if (add(item, true)) return selected;
    }
  }
  for (const item of sorted) {
    if (add(item, false)) return selected;
  }
  for (const item of sorted) {
    if (selected.length >= limit) return selected;
    if (!item || selectedKeys.has(item.dedupe_key)) continue;
    const category = safeText(item.payload?.category || 'other');
    const companyKey = newsCompanyKeyForItem(item);
    selected.push(item);
    selectedKeys.add(item.dedupe_key);
    categoryCounts[category] = (categoryCounts[category] || 0) + 1;
    if (companyKey) companyCounts[companyKey] = (companyCounts[companyKey] || 0) + 1;
  }
  return selected;
}

function newsWindowForDate(dateText: string) {
  const match = String(dateText || '').match(/^(\d{4})-(\d{2})-(\d{2})$/u);
  if (!match) throw new Error('date must look like YYYY-MM-DD');
  const windowEnd = new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3]), -2, 0, 0));
  const windowHours = new Date(windowEnd.getTime() + NEWS_KST_OFFSET_MS).getUTCDay() === 1 ? 72 : 24;
  const windowStart = new Date(windowEnd.getTime() - windowHours * NEWS_HOUR_MS);
  return { windowStart, windowEnd, windowHours };
}

function newsDefaultCollectDateKey(now = new Date()) {
  const kstNow = new Date(now.getTime() + NEWS_KST_OFFSET_MS);
  if (kstNow.getUTCHours() < 7) kstNow.setUTCDate(kstNow.getUTCDate() - 1);
  return kstNow.toISOString().slice(0, 10);
}

async function fetchNewsRss(url: URL) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), NEWS_RSS_FETCH_TIMEOUT_MS);
  try {
    const response = await fetch(url, { headers: { 'user-agent': 'logistics-gate6-news-collector/2.0' }, signal: controller.signal });
    if (!response.ok) return '';
    return await response.text();
  } catch {
    return '';
  } finally {
    clearTimeout(timeout);
  }
}

async function fetchGoogleNewsRows(query: string, days: number) {
  const url = new URL(NEWS_GOOGLE_RSS_URL);
  url.searchParams.set('q', `${query} when:${Math.max(1, Math.min(days, 14))}d`);
  url.searchParams.set('hl', 'ko');
  url.searchParams.set('gl', 'KR');
  url.searchParams.set('ceid', 'KR:ko');
  return newsParseRssItems(await fetchNewsRss(url), 'google_news_rss', query);
}

async function fetchGoogleNewsRowsForDateRange(query: string, windowStart: Date, windowEnd: Date) {
  const startKey = windowStart.toISOString().slice(0, 10);
  const endKey = new Date(windowEnd.getTime() + NEWS_HOUR_MS * 24).toISOString().slice(0, 10);
  const url = new URL(NEWS_GOOGLE_RSS_URL);
  url.searchParams.set('q', `${query} after:${startKey} before:${endKey}`);
  url.searchParams.set('hl', 'ko');
  url.searchParams.set('gl', 'KR');
  url.searchParams.set('ceid', 'KR:ko');
  return newsParseRssItems(await fetchNewsRss(url), 'google_news_rss_backfill', query);
}

async function fetchBingNewsRows(query: string) {
  const url = new URL(NEWS_BING_RSS_URL);
  url.searchParams.set('q', query);
  url.searchParams.set('format', 'rss');
  url.searchParams.set('setlang', 'ko-KR');
  url.searchParams.set('cc', 'KR');
  return newsParseRssItems(await fetchNewsRss(url), 'bing_news_rss', query);
}

async function collectNewsRowsForWindow(windowStart: Date, windowEnd: Date, days: number, options: { minimumScore?: number; backfillMode?: string } = {}) {
  const minimumScore = Math.max(1, Number(options.minimumScore || 2));
  const seen = new Map<string, NewsCollectorItem>();
  const sourceStats: Record<string, number> = {};
  for (let index = 0; index < NEWS_SEARCH_QUERIES.length; index += NEWS_RSS_QUERY_BATCH_SIZE) {
    const queryBatch = NEWS_SEARCH_QUERIES.slice(index, index + NEWS_RSS_QUERY_BATCH_SIZE);
    const batchRows = await Promise.all(queryBatch.map(async (query) => [
      ...(await fetchGoogleNewsRows(query, days).catch(() => [])),
      ...(await fetchBingNewsRows(query).catch(() => [])),
    ]));
    for (const row of batchRows.flat()) {
      sourceStats[String(row.source_name)] = (sourceStats[String(row.source_name)] || 0) + 1;
      const publishedAt = new Date(row.pubDate);
      if (Number.isNaN(publishedAt.getTime())) continue;
      if (publishedAt < windowStart || publishedAt > windowEnd) continue;
      const publisher = newsPublisher(row as Record<string, unknown>);
      const title = newsCleanTitle(row.title, publisher);
      const summary = newsStripHtml(row.description).slice(0, 500);
      const canonical = newsCanonicalUrl(row.link);
      const titleHash = await sha256Text(newsNormalizeTitle(title));
      const urlHash = canonical ? await sha256Text(canonical) : '';
      const dedupeKey = urlHash ? `url:${urlHash}` : `title:${titleHash}`;
      const fallbackDedupeKey = `publisher-title-time:${await sha256Text(`${publisher}:${titleHash}:${publishedAt.toISOString().slice(0, 13)}`)}`;
      const scored = newsScore({ title, summary });
      if (scored.score < minimumScore) continue;
      const next: NewsCollectorItem = {
        dedupe_key: dedupeKey,
        canonical_url: canonical,
        original_url: canonical,
        title,
        publisher,
        published_at: publishedAt.toISOString(),
        summary,
        importance_score: scored.score,
        matched_keywords: scored.matched,
        source_name: safeText(row.source_name),
        payload: {
          query: row.query,
          raw_pub_date: row.pubDate,
          fallback_dedupe_key: fallbackDedupeKey,
          category: scored.category,
          company_key: scored.company?.key || '',
          company_label: scored.company?.label || '',
          backfill_mode: options.backfillMode || '',
        },
      };
      const current = seen.get(dedupeKey) || seen.get(fallbackDedupeKey);
      if (!current || Number(next.importance_score) > Number(current.importance_score)) {
        seen.set(dedupeKey, next);
        seen.set(fallbackDedupeKey, next);
      }
    }
  }
  const candidates = [...new Map([...seen.values()].map((item) => [item.dedupe_key, item])).values()];
  return {
    items: newsSelectBalancedItems(candidates, 10),
    sourceStats,
    candidateCount: candidates.length,
  };
}

async function collectNewsRowsForWindowWithExpansion(windowStart: Date, windowEnd: Date, days: number) {
  const strict = await collectNewsRowsForWindow(windowStart, windowEnd, days);
  let selected = strict;
  let historicalBackfill = false;
  let relaxedBackfill = false;
  if (strict.items.length >= NEWS_MIN_DAILY_ITEMS) {
    return {
      ...strict,
      strictItemCount: strict.items.length,
      expandedToRecent7d: false,
      expandedWindowStart: windowStart,
      historicalBackfill: false,
      relaxedBackfill: false,
      strictWindowOnly: true,
    };
  }
  if (selected.items.length < NEWS_MIN_DAILY_ITEMS) {
    const historical = await collectNewsRowsForHistoricalWindow(windowStart, windowEnd).catch(() => null);
    if (historical?.items?.length) {
      const mergedItems = newsSelectBalancedItems([...selected.items, ...historical.items], 10);
      if (mergedItems.length > selected.items.length) {
        const sourceStats: Record<string, number> = { ...(selected.sourceStats || {}) };
        for (const [key, value] of Object.entries(historical.sourceStats || {})) {
          sourceStats[key] = (sourceStats[key] || 0) + Number(value || 0);
        }
        selected = {
          items: mergedItems,
          sourceStats,
          candidateCount: Math.max(Number(selected.candidateCount || 0), 0) + Math.max(Number(historical.candidateCount || 0), 0),
        };
        historicalBackfill = true;
      }
    }
  }
  if (selected.items.length < NEWS_MIN_DAILY_ITEMS) {
    const relaxed = await collectNewsRowsForWindow(windowStart, windowEnd, days, {
      minimumScore: 1,
      backfillMode: 'relaxed_same_window',
    }).catch(() => null);
    if (relaxed?.items?.length) {
      const mergedItems = newsSelectBalancedItems([...selected.items, ...relaxed.items], 10);
      if (mergedItems.length > selected.items.length) {
        const sourceStats: Record<string, number> = { ...(selected.sourceStats || {}) };
        for (const [key, value] of Object.entries(relaxed.sourceStats || {})) {
          sourceStats[key] = (sourceStats[key] || 0) + Number(value || 0);
        }
        selected = {
          items: mergedItems,
          sourceStats,
          candidateCount: Math.max(Number(selected.candidateCount || 0), 0) + Math.max(Number(relaxed.candidateCount || 0), 0),
        };
        relaxedBackfill = true;
      }
    }
  }
  return {
    ...selected,
    strictItemCount: strict.items.length,
    expandedToRecent7d: false,
    expandedWindowStart: windowStart,
    historicalBackfill,
    relaxedBackfill,
    strictWindowOnly: true,
  };
}

async function collectNewsRowsForHistoricalWindow(windowStart: Date, windowEnd: Date) {
  const seen = new Map<string, NewsCollectorItem>();
  const sourceStats: Record<string, number> = {};
  for (let index = 0; index < NEWS_SEARCH_QUERIES.length; index += NEWS_RSS_QUERY_BATCH_SIZE) {
    const queryBatch = NEWS_SEARCH_QUERIES.slice(index, index + NEWS_RSS_QUERY_BATCH_SIZE);
    const batchRows = await Promise.all(queryBatch.map(
      (query) => fetchGoogleNewsRowsForDateRange(query, windowStart, windowEnd).catch(() => []),
    ));
    for (const row of batchRows.flat()) {
      sourceStats[String(row.source_name)] = (sourceStats[String(row.source_name)] || 0) + 1;
      const publishedAt = new Date(row.pubDate);
      if (Number.isNaN(publishedAt.getTime())) continue;
      if (publishedAt < windowStart || publishedAt > windowEnd) continue;
      const publisher = newsPublisher(row as Record<string, unknown>);
      const title = newsCleanTitle(row.title, publisher);
      const summary = newsStripHtml(row.description).slice(0, 500);
      const canonical = newsCanonicalUrl(row.link);
      const titleHash = await sha256Text(newsNormalizeTitle(title));
      const urlHash = canonical ? await sha256Text(canonical) : '';
      const dedupeKey = urlHash ? `url:${urlHash}` : `title:${titleHash}`;
      const fallbackDedupeKey = `publisher-title-time:${await sha256Text(`${publisher}:${titleHash}:${publishedAt.toISOString().slice(0, 13)}`)}`;
      const scored = newsScore({ title, summary });
      if (scored.score < 2) continue;
      const next: NewsCollectorItem = {
        dedupe_key: dedupeKey,
        canonical_url: canonical,
        original_url: canonical,
        title,
        publisher,
        published_at: publishedAt.toISOString(),
        summary,
        importance_score: scored.score,
        matched_keywords: scored.matched,
        source_name: safeText(row.source_name),
        payload: {
          query: row.query,
          raw_pub_date: row.pubDate,
          fallback_dedupe_key: fallbackDedupeKey,
          category: scored.category,
          company_key: scored.company?.key || '',
          company_label: scored.company?.label || '',
          restoration_mode: 'historical_rss_reconstruction',
          restoration_note: '원본 10건 상세 artifact를 찾지 못해 2026-06-17 07:00 KST 직전 24시간 기준으로 재수집 기반 재구성했습니다.',
        },
      };
      const current = seen.get(dedupeKey) || seen.get(fallbackDedupeKey);
      if (!current || Number(next.importance_score) > Number(current.importance_score)) {
        seen.set(dedupeKey, next);
        seen.set(fallbackDedupeKey, next);
      }
    }
  }
  const candidates = [...new Map([...seen.values()].map((item) => [item.dedupe_key, item])).values()];
  return {
    items: newsSelectBalancedItems(candidates, 10),
    sourceStats,
    candidateCount: candidates.length,
  };
}

type NewsStorageHealth = {
  selectedDate: string;
  itemCount: number;
  completedAt: string;
};

function newsRunSummary(health: NewsStorageHealth) {
  const completed = health.itemCount >= NEWS_MIN_DAILY_ITEMS;
  const window = newsWindowForDate(health.selectedDate);
  return {
    run_key: `daily-news:${health.selectedDate}:0700KST`,
    run_status: completed ? 'completed' : health.itemCount > 0 ? 'incomplete' : 'no_run',
    completed_at: completed ? health.completedAt : null,
    scheduled_for: window.windowEnd.toISOString(),
    window_start: window.windowStart.toISOString(),
    window_end: window.windowEnd.toISOString(),
    source_summary: {
      collector_version: NEWS_COLLECTOR_VERSION,
      item_count: health.itemCount,
      minimum_item_count: NEWS_MIN_DAILY_ITEMS,
      window_hours: window.windowHours,
      strict_window_only: true,
      strict_24h_window: window.windowHours === 24,
      expanded_to_recent_7d: false,
      expanded_recent_days: 0,
    },
  };
}

async function readNewsStorageHealth(ctx: Context, selectedDate: string): Promise<NewsStorageHealth> {
  const result = await ctx.serviceClient
    .from('ll_news_items')
    .select('ingested_at', { count: 'exact' })
    .eq('news_date', selectedDate)
    .order('ingested_at', { ascending: false, nullsFirst: false })
    .limit(1);
  if (result.error) throw new Error(result.error.message);
  return {
    selectedDate,
    itemCount: Number(result.count || 0),
    completedAt: safeText((result.data?.[0] as Record<string, unknown> | undefined)?.ingested_at),
  };
}

async function collectAndStoreNewsRun(ctx: Context, dateText: string, limit = 10, force = false) {
  const selectedDate = /^\d{4}-\d{2}-\d{2}$/u.test(dateText) ? dateText : newsDefaultCollectDateKey();
  const strictWindow = newsWindowForDate(selectedDate);
  const strictDays = Math.ceil(strictWindow.windowHours / 24);
  const before = await readNewsStorageHealth(ctx, selectedDate);
  if (!force && before.itemCount >= NEWS_MIN_DAILY_ITEMS) {
    return { run: newsRunSummary(before), item_count: before.itemCount, status: 'existing' };
  }

  const collected = await collectNewsRowsForWindowWithExpansion(strictWindow.windowStart, strictWindow.windowEnd, strictDays);
  const itemRows = collected.items.slice(0, Math.max(limit, 10)).map((item) => ({
    news_item_id: crypto.randomUUID(),
    news_date: selectedDate,
    ingested_at: new Date().toISOString(),
    dedupe_key: item.dedupe_key,
    canonical_url: item.canonical_url,
    original_url: item.original_url,
    title: item.title,
    publisher: item.publisher,
    published_at: item.published_at,
    summary: item.summary,
    importance_score: item.importance_score,
    matched_keywords: item.matched_keywords,
    source_name: item.source_name,
  }));
  if (itemRows.length < NEWS_MIN_DAILY_ITEMS) {
    throw new NewsRunCollectionError(409, 'Insufficient logistics news items collected', {
      selected_date: selectedDate,
      collected_item_count: itemRows.length,
      minimum_item_count: NEWS_MIN_DAILY_ITEMS,
      candidate_count: collected.candidateCount || collected.items.length,
      source_stats: collected.sourceStats,
      preserved_stored_items: before.itemCount,
    });
  }

  const itemResult = await ctx.serviceClient
    .from('ll_news_items')
    .upsert(itemRows, { onConflict: 'news_date,dedupe_key' });
  if (itemResult.error) throw new Error(itemResult.error.message);
  const readback = await readNewsStorageHealth(ctx, selectedDate);
  if (readback.itemCount < NEWS_MIN_DAILY_ITEMS) {
    throw new NewsRunCollectionError(502, 'Logistics news item readback is incomplete', {
      selected_date: selectedDate,
      collected_item_count: itemRows.length,
      readback_item_count: readback.itemCount,
      minimum_item_count: NEWS_MIN_DAILY_ITEMS,
    });
  }
  return { run: newsRunSummary(readback), item_count: readback.itemCount, status: 'collected' };
}

async function callNewsList(ctx: Context, payload: Record<string, unknown>) {
  const limit = Math.min(Math.max(Number(payload.limit || 10), 1), 30);
  const selectedDate = safeText(firstDefined(payload.date, payload.news_date, payload.selected_date));
  const hasDateFilter = /^\d{4}-\d{2}-\d{2}$/u.test(selectedDate);
  let effectiveDate = hasDateFilter ? selectedDate : '';
  if (!effectiveDate) {
    const latestDateResult = await ctx.serviceClient
      .from('ll_news_items')
      .select('news_date')
      .order('news_date', { ascending: false, nullsFirst: false })
      .limit(1)
      .maybeSingle();
    if (latestDateResult.error) {
      if (isMissingRelationError(latestDateResult.error)) return jsonResponse({ ok: true, data: { status: 'missing_schema', data_validated: false, validation_status: 'missing_schema', items: [], empty_message: NEWS_EMPTY_MESSAGE, generated_at: new Date().toISOString() } }, 200, ctx.origin);
      return fail(500, 'Failed to read logistics news', ctx.origin, { error: latestDateResult.error.message });
    }
    effectiveDate = safeText((latestDateResult.data as Record<string, unknown> | null)?.news_date);
  }

  let data: NewsCollectorItem[] = [];
  let health: NewsStorageHealth = { selectedDate: effectiveDate, itemCount: 0, completedAt: '' };
  if (effectiveDate) {
    try {
      health = await readNewsStorageHealth(ctx, effectiveDate);
      const itemResult = await ctx.serviceClient
        .from('ll_news_items')
        .select('news_item_id,dedupe_key,canonical_url,original_url,title,publisher,published_at,summary,importance_score,matched_keywords,source_name,news_date,ingested_at')
        .eq('news_date', effectiveDate)
        .order('published_at', { ascending: false, nullsFirst: false })
        .limit(Math.min(Math.max(limit * 3, limit), 30));
      if (itemResult.error) throw itemResult.error;
      data = (itemResult.data || []) as NewsCollectorItem[];
    } catch (error) {
      if (isMissingRelationError(error)) return jsonResponse({ ok: true, data: { status: 'missing_schema', data_validated: false, validation_status: 'missing_schema', items: [], empty_message: NEWS_EMPTY_MESSAGE, generated_at: new Date().toISOString() } }, 200, ctx.origin);
      return fail(500, 'Failed to read logistics news', ctx.origin, { error: error instanceof Error ? error.message : String(error) });
    }
  }
  const visibleItems = newsRemoveNearDuplicateStories(data).slice(0, limit);
  const latestRun = effectiveDate ? newsRunSummary(health) : null;
  const runStatus = latestRun ? safeText(latestRun.run_status) : 'no_run';
  const hasMinimumVisibleItems = visibleItems.length >= NEWS_MIN_DAILY_ITEMS;
  const newsDataValidated = Boolean(latestRun && runStatus === 'completed' && hasMinimumVisibleItems);
  const validationStatus = latestRun && runStatus === 'completed' && !hasMinimumVisibleItems ? 'incomplete' : runStatus;
  return jsonResponse({ ok: true, data: {
    status: runStatus,
    data_validated: newsDataValidated,
    validation_status: validationStatus,
    collection_mode: 'precollected_read_only',
    collect_on_read: false,
    selected_date: hasDateFilter ? selectedDate : effectiveDate,
    latest_run: latestRun,
    items: visibleItems,
    item_count: visibleItems.length,
    empty_message: NEWS_EMPTY_MESSAGE,
    generated_at: new Date().toISOString(),
  } }, 200, ctx.origin);
}

async function callNewsCollectRun(ctx: Context, payload: Record<string, unknown>) {
  if (!await canUseServerFeature(ctx, 'permission_admin')) return fail(403, 'Permission administration is required', ctx.origin);
  if (!checkRateLimit(ctx.user.id, 'news/collect-run', 3, 60_000)) return fail(429, 'Rate limit exceeded', ctx.origin);
  const requestedDate = safeText(firstDefined(payload.date, payload.news_date, payload.selected_date));
  const selectedDate = /^\d{4}-\d{2}-\d{2}$/u.test(requestedDate) ? requestedDate : newsDefaultCollectDateKey();
  const limit = Math.min(Math.max(Number(payload.limit || 10), 1), 30);
  const force = payload.force === true;
  try {
    const collected = await collectAndStoreNewsRun(ctx, selectedDate, limit, force);
    return jsonResponse({ ok: true, data: {
      status: collected.status,
      selected_date: selectedDate,
      latest_run: collected.run,
      item_count: collected.item_count,
      force,
      collection_mode: 'admin_precollect',
      collect_on_read: false,
      generated_at: new Date().toISOString(),
    } }, 200, ctx.origin);
  } catch (error) {
    if (error instanceof NewsRunCollectionError) {
      return fail(error.status, error.message, ctx.origin, {
        selected_date: selectedDate,
        ...error.details,
      });
    }
    return fail(500, 'Failed to collect logistics news run', ctx.origin, {
      selected_date: selectedDate,
      error: error instanceof Error ? error.message : String(error),
    });
  }
}

async function callNewsRestore20260617(ctx: Context) {
  if (!await canUseServerFeature(ctx, 'permission_admin')) return fail(403, 'Permission administration is required', ctx.origin);
  if (!checkRateLimit(ctx.user.id, 'news/restore-20260617', 6, 60_000)) return fail(429, 'Rate limit exceeded', ctx.origin);
  const targetDate = '2026-06-17';
  const beforeResult = await ctx.serviceClient
    .from('ll_news_items')
    .select('dedupe_key,title,publisher,published_at,canonical_url')
    .eq('news_date', targetDate)
    .order('published_at', { ascending: false, nullsFirst: false });
  if (beforeResult.error) return fail(500, 'Failed to read logistics news items', ctx.origin, { error: beforeResult.error.message });

  const strictWindow = newsWindowForDate(targetDate);
  const collected = await collectNewsRowsForHistoricalWindow(strictWindow.windowStart, strictWindow.windowEnd);
  const itemRows = collected.items.slice(0, 10).map((item) => ({
    news_item_id: crypto.randomUUID(),
    news_date: targetDate,
    ingested_at: new Date().toISOString(),
    dedupe_key: item.dedupe_key,
    canonical_url: item.canonical_url,
    original_url: item.original_url,
    title: item.title,
    publisher: item.publisher,
    published_at: item.published_at,
    summary: item.summary,
    importance_score: item.importance_score,
    matched_keywords: item.matched_keywords,
    source_name: item.source_name,
  }));
  if (itemRows.length < 8) {
    await auditOptional(ctx.serviceClient, ctx.user.id, 'news/restore-20260617/insufficient_candidates', 409, {
      before_count: beforeResult.data?.length || 0,
      candidate_count: collected.candidateCount,
      selected_count: itemRows.length,
      source_stats: collected.sourceStats,
    });
    return jsonResponse({ ok: false, message: 'Insufficient reconstruction candidates', data: {
      selected_date: targetDate,
      before_count: beforeResult.data?.length || 0,
      candidate_count: collected.candidateCount,
      selected_count: itemRows.length,
      source_stats: collected.sourceStats,
      note: '원본 10건 상세 artifact를 찾지 못했고, 재구성 후보도 8건 미만입니다.',
    } }, 409, ctx.origin);
  }

  const { error: itemError } = await ctx.serviceClient
    .from('ll_news_items')
    .upsert(itemRows, { onConflict: 'news_date,dedupe_key' });
  if (itemError) return fail(500, 'Failed to restore logistics news items', ctx.origin, { error: itemError.message });

  const afterResult = await ctx.serviceClient
    .from('ll_news_items')
    .select('dedupe_key,title,publisher,published_at,canonical_url')
    .eq('news_date', targetDate)
    .order('published_at', { ascending: false, nullsFirst: false });
  if (afterResult.error) return fail(500, 'Failed to read restored logistics news items', ctx.origin, { error: afterResult.error.message });

  const beforeKeys = new Set(((beforeResult.data || []) as Record<string, unknown>[]).map((item) => safeText(item.dedupe_key)).filter(Boolean));
  await audit(ctx.serviceClient, ctx.user.id, 'news/restore-20260617', 200, {
    selected_date: targetDate,
    before_count: beforeResult.data?.length || 0,
    after_count: afterResult.data?.length || 0,
    inserted_or_updated: itemRows.length,
  });
  return jsonResponse({ ok: true, data: {
    selected_date: targetDate,
    before_count: beforeResult.data?.length || 0,
    after_count: afterResult.data?.length || 0,
    inserted_or_updated: itemRows.length,
    preserved_existing_keys: [...beforeKeys],
    restored_items: ((afterResult.data || []) as Record<string, unknown>[]).map((item) => ({
      dedupe_key: safeText(item.dedupe_key),
      title: safeText(item.title),
      publisher: safeText(item.publisher),
      published_at: safeText(item.published_at),
      canonical_url: safeText(item.canonical_url),
    })),
    note: '원본 10건 상세 artifact를 찾지 못해 2026-06-17 07:00 KST 직전 24시간 기준으로 재수집 기반 재구성했습니다.',
  } }, 200, ctx.origin);
}

function normalizeLeaseEventPayload(payload: Record<string, unknown>) {
  const eventType = safeText(payload.event_type || payload.eventType || 'correction');
  const sourceRows = Array.isArray(payload.source_rows) ? payload.source_rows : [];
  const cellEdits = Array.isArray(payload.cell_edits) ? payload.cell_edits : [];
  return {
    kind: 'lease_contract_event',
    event_type: LEASE_EVENT_TYPES.has(eventType) ? eventType : 'correction',
    asset_id: safeText(payload.asset_id || payload.assetId),
    asset_name: safeText(payload.asset_name || payload.assetName),
    tenant_name: safeText(payload.tenant_name || payload.tenantName || payload.tenant_master_name),
    tenant_id: safeText(payload.tenant_id || payload.tenantId),
    lease_id: safeText(payload.lease_id || payload.leaseId),
    lease_space_id: safeText(payload.lease_space_id || payload.leaseSpaceId),
    effective_date: safeText(payload.effective_date || payload.effectiveDate),
    summary: safeText(payload.summary || payload.reason || payload.notes),
    before: redactSensitivePayload(payload.before || {}),
    after: redactSensitivePayload(payload.after || {}),
    source_rows: redactSensitivePayload(sourceRows),
    cell_edits: redactSensitivePayload(cellEdits),
    source_refs: redactSensitivePayload(payload.source_refs || []),
  };
}

type LeaseEventWritePlan = {
  mode: string;
  status: 'ready' | 'blocked';
  required_missing: string[];
  duplicate_findings: Record<string, unknown>[];
  warnings: string[];
  writes: Record<string, unknown>[];
  resolved: Record<string, unknown>;
};

type LeaseEventAppliedWrite = {
  operation: 'insert' | 'update' | 'source_only';
  table: string;
  primaryKeyField: string;
  id: string;
  before?: Record<string, unknown> | null;
  after?: Record<string, unknown> | null;
  sourceOnlyRollback?: { cell: NormalizedEditCell; previous: Record<string, unknown> | null; insertedId: unknown };
};

